-- 078_seed_curriculum_content.sql
--
-- Phase 2 — bulk seed of the 250-row Mioshy curriculum from the CSV
-- 'מסע-זוגיות-מערכת-תוכן' onto journey_programs / journey_categories /
-- journey_items. Generated by scripts/generate_curriculum_migration.py;
-- regenerate after CSV edits and replay to update content in place.
--
-- Idempotent — uses ON CONFLICT (category_id, slug) DO UPDATE so
-- re-running adopts the latest CSV without duplicating rows. Items in
-- the database whose slug isn't in the CSV are LEFT UNTOUCHED — this
-- script never deletes.
--
-- Strategy:
--   1. Ensure program 'ha-masa-ha-shalem' (המסע השלם) exists.
--   2. Bind the 5 priority categories (communication / intimacy /
--      emotional_connection / friendship / family) to the program if
--      they're currently program-less.
--   3. UPSERT 250 lessons keyed on (category_id, slug). Slugs are
--      deterministic (csv-s{stage}-{cat}-{nnn}) so re-runs hit the
--      same rows.
--
-- All lesson blocks (insight / mistakes / metaphor / measurement /
-- do / don't / progress / source) populated from migration 077's
-- new columns.

BEGIN;

-- ── 1. Program ───────────────────────────────────────────────────
INSERT INTO public.journey_programs (
  slug, name_he, name_en, description_he, description_en,
  default_anchor, is_active, sort_weight
) VALUES (
  'ha-masa-ha-shalem',
  $b$המסע השלם$b$,
  $b$The Full Journey$b$,
  $b$תוכנית הליווי המלאה של מיאושי — ארבעה שלבים, חמש קטגוריות, 250 שיעורים מובנים. מבוסס על מחקר של גוטמן, צ׳פמן, פרל, סו ג׳ונסון ועוד.$b$,
  $b$The full Mioshy coaching program — four stages, five categories, 250 structured lessons. Grounded in research from Gottman, Chapman, Perel, Sue Johnson and others.$b$,
  'purchase', true, 100
)
ON CONFLICT (slug) DO UPDATE SET
  name_he      = EXCLUDED.name_he,
  name_en      = EXCLUDED.name_en,
  description_he = EXCLUDED.description_he,
  description_en = EXCLUDED.description_en,
  is_active    = true,
  updated_at   = now();

-- ── 2. Bind the 5 priority categories to this program (only if NULL) ──
UPDATE public.journey_categories c
SET program_id = (SELECT id FROM public.journey_programs WHERE slug = 'ha-masa-ha-shalem')
WHERE c.program_id IS NULL
  AND c.assessment_priority_key IN ('communication','intimacy','emotional_connection','friendship','family');

-- ── 3. Resolve category ids into a CTE for the upsert below ──────

-- Row #1: שלב 1 · תקשורת זוגית · שפת האהבה שלי — ושלך
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-001',
  $b$שפת האהבה שלי — ושלך$b$,
  $b$כשגארי צ׳פמן עבד עם זוגות ברפואה רגשית בשנות ה-90, הוא הבחין שזוגות רבים אהבו זה את זה — ובכל זאת הרגישו לא נראים. הוא זיהה דפוס: כל אדם מבין אהבה דרך 'שפה' מועדפת, ושפת ההורה לא בהכרח שפת בן/בת הזוג.

חמש השפות הן: (1) מילים מחזקות — "אתה מדהים", "אני גאה בך". (2) זמן איכות — תשומת לב מלאה, בלי טלפונים. (3) מתנות קטנות — לא בגלל הערך, בגלל המחשבה. (4) מעשי שירות — לעשות עבורו/ה משהו פרקטי, מבלי שיבקש. (5) מגע פיזי — חיבוק, ליטוף, קרבה גופנית לא מינית.

החוכמה היא לא רק לזהות את השפה של בן/בת הזוג, אלא להבין שכשאני מדבר/ת איתו/ה בשפה שלי — בעיקר אם זו שפה שונה משלו/ה — האהבה שלי לא מתורגמת. דמיין/י שאת/ה מביא/ה זר פרחים גדול לבן/בת זוג ששפתו/ה היא 'מעשי שירות', והוא/היא היה מעדיף/ה שתעשה/י את הכלים. הפרחים יפים — אבל זה לא נשמע כ"אני אוהב/ת אותך" באוזניים שלו/ה.

צ׳פמן מציע מבחן פשוט: שאל/י את עצמך באיזו שפה את/ה הכי מבקש/ת אהבה — איך את/ה מתלונן/ת. אם הביקורת היומית שלך היא 'אנחנו לא מדברים', השפה שלך כנראה זמן איכות. אם היא 'אתה לא עוזר לי', זה מעשי שירות. הביקורת היא חלון לצורך הלא ממומש.

מחקרי גוטמן הוסיפו עומק: זוגות מצליחים לא רק יודעים את השפה של השני — הם מתאמנים בה גם כשהיא לא טבעית להם. גבר ששפתו 'מעשי שירות' לומד לכתוב פתק יומי לאשתו ש'מילים מחזקות' היא שפתה. אישה ש'זמן איכות' היא שפתה לומדת לחבק את בן זוגה כשנכנס הביתה, אם 'מגע פיזי' זו שלו. זה לא מזויף — זה תרגום מודע.

התרגול לא נשבר ביום הראשון. ההצלחה היא בעקביות של חודש: שלוש פעמים בשבוע, באופן מודע, בשפה של השני. אחרי חודש, רוב הזוגות מדווחים שהזוגיות 'הרגישה אחרת' — לא כי משהו הוסיף, אלא כי האהבה התחילה להגיע.$b$,
  $b$כל אחד מדרג בנפרד את חמש השפות לפי החשיבות שלהן בשבילו. אחר כך משווים. בוחרים שפה אחת של השני שתתרגלו השבוע, ועושים אותה לפחות שלוש פעמים — בלי להזכיר שאתם 'מתרגלים'.$b$,
  10001, 0, true, 'both',
  1,
  $b$Gary Chapman, The 5 Love Languages$b$, $b$Gary Chapman, The 5 Love Languages$b$,
  $b$גארי צ׳פמן זיהה חמש שפות אהבה: מילים מחזקות, זמן איכות, מתנות, מעשי שירות, מגע פיזי. כל אדם נותן ומקבל אהבה בשפה דומיננטית אחת — אבל רוב הזוגות מדברים את השפה שלהם ומצפים מבן/בת הזוג לתרגם.$b$, $b$1) להניח שאיך שאני נותן/ת = איך שהשני מקבל. 2) לפסול שפה שלא טבעית לי ("אני לא בנאדם של מילים" — וזו בדיוק השפה שהוא/היא צריך/ה). 3) לוותר אחרי כישלון אחד במקום לתרגל.$b$, $b$כמו רדיו — יכול להתנגן שיר מקסים, אבל אם בן/בת הזוג מכוון/ת לתחנה אחרת, הוא/היא ישמע/תשמע רק רעש.$b$,
  $b$ספרו השבוע: כמה פעמים נתתם בשפה של השני, לעומת בשפה שלכם.$b$, $b$תרגל/י את השפה של בן/בת הזוג לפחות 3 פעמים השבוע, באופן מודע ולא מתוייג.$b$, $b$אל תוותר/י על שפה רק כי היא לא טבעית לך. הגוף לומד שפות חדשות.$b$, $b$את/ה תופס/ת את עצמך בוחר/ת מתנה / מילה / מגע לפי השפה של השני, לא לפי הרגל אישי.$b$
)
ON CONFLICT (category_id, slug) DO UPDATE SET
  title_he              = EXCLUDED.title_he,
  body_he               = EXCLUDED.body_he,
  task_he               = EXCLUDED.task_he,
  sort_order            = EXCLUDED.sort_order,
  is_active             = true,
  audience              = EXCLUDED.audience,
  stage                 = EXCLUDED.stage,
  source_attribution_he = EXCLUDED.source_attribution_he,
  source_attribution_en = EXCLUDED.source_attribution_en,
  expert_insight_he     = EXCLUDED.expert_insight_he,
  common_mistakes_he    = EXCLUDED.common_mistakes_he,
  metaphor_he           = EXCLUDED.metaphor_he,
  measurement_he        = EXCLUDED.measurement_he,
  do_this_week_he       = EXCLUDED.do_this_week_he,
  dont_this_week_he     = EXCLUDED.dont_this_week_he,
  progress_marker_he    = EXCLUDED.progress_marker_he,
  updated_at            = now();

-- Row #2: שלב 1 · תקשורת זוגית · הקשבה אקטיבית — לראות לפני לתקן
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-002',
  $b$הקשבה אקטיבית — לראות לפני לתקן$b$,
  $b$ג'ון גוטמן וצוותו ב-Love Lab באוניברסיטת וושינגטון צילמו אלפי זוגות בשיחות אינטימיות לאורך שלושים שנה. אחד הממצאים החזקים ביותר: זוגות שמדורגים גבוה בסיפוק הם אלה שמקשיבים אחרת.

הקשבה אקטיבית, כפי שגוטמן מגדיר, אינה רק שתיקה. היא שלושה דברים בו זמנית: (1) נוכחות מלאה — גוף, פנים, עיניים מופנות. (2) אי-שיפוט — לא ממיין/ת בפנים את מה שטוב או רע במה שנאמר. (3) שאילת שאלות הבהרה — "מה הרגשת באותו רגע?", "מה היה החלק הכי קשה?".

הסיבה שזה כל כך חשוב היא נוירולוגית. כשבן/בת זוג מספר/ת על משהו קשה ומקבל/ת תגובה של פתרון מהיר ('פשוט תעשה כך'), המוח מפרש את זה כ'אתה לא רואה אותי, אתה רואה את הבעיה'. גם אם הפתרון נכון, ההרגשה היא של חוסר ראייה. במקום אהבה, נוצר ניתוק קטן — ואלה מצטברים.

זוגות מצליחים יודעים להבחין בין שלוש סיטואציות: כשבן/בת הזוג מבקש/ת פתרון, כשהוא/היא מבקש/ת אישור, וכשהוא/היא מבקש/ת רק נוכחות. רוב הסיטואציות הקשות הן השלישית — נוכחות. גברים בעיקר מתקשים בזה, כי תרבותית הם מאומנים לתקן. הצעד הראשון הוא לשאול: "את/ה רוצה שאקשיב או שאעזור?" — ולכבד את התשובה.

התרגול היומיומי שגוטמן ממליץ עליו הוא 'שיחת מדרגת המעבר' — חמש דקות בערב שמיועדות רק להעברת מטרה ('איך היה היום, מה היה לחוץ, מה היה כיף') — בלי פתרונות, בלי עצות, רק קבלה. אחרי שבוע של שיחות כאלה, רוב הזוגות מדווחים שהם מרגישים יותר קרובים — בלי שדיברו על שום בעיה.

ההקשבה היא לא טכניקה — היא תפיסה. שינוי מ"מה אני אגיד עכשיו?" ל"מה הוא/היא צריך/ה ממני עכשיו?". כשזה הופך להרגל, הזוגיות הופכת לבית — מקום שבו אנחנו באמת נשמעים.$b$,
  $b$תרגיל ה-15 דקות: כל אחד מדבר 7 דקות על נושא שמטריד אותו (לא קשור לבן/בת הזוג). השני רק מקשיב. אחר כך השני מסכם מה שמע — בלי להוסיף דעה. רק אז מתחלפים. בסוף: שאלו אחד את השני 'מה היה הרגע שהרגשת/י באמת נשמע/ת?'.$b$,
  10002, 0, true, 'both',
  1,
  $b$John Gottman, The Seven Principles for Making Marriage Work$b$, $b$John Gottman, The Seven Principles for Making Marriage Work$b$,
  $b$גוטמן זיהה שזוגות מאושרים מקשיבים כדי להבין, לא כדי להגיב. הם שואלים שאלות הבהרה לפני שהם פותרים. רוב הזוגות מקפצים ל'פתרון' לפני שבן/בת הזוג סיים/ה לדבר — וזה רגע שבו הקול הולך לאיבוד.$b$, $b$1) להציע פתרון בעוד הצד השני באמצע משפט. 2) לחשוב שהקשבה היא אישור — אפשר להקשיב בלי להסכים. 3) להתחיל את התגובה ב"כן, אבל". 4) להפנות את הסיפור לעצמך ("גם לי קרה ש...").$b$, $b$הקשבה אמיתית היא כמו לטעום מנה ארוכה לפני שאומרים אם היא מלוחה. אם אומרים מהביס הראשון — מפספסים את הטעם השלם.$b$,
  $b$השבוע: כמה פעמים תפסתם את עצמכם פותרים לפני שבן/בת הזוג סיים/ה לדבר?$b$, $b$פעם ביום אחד — שאל/י "את/ה רוצה שאקשיב או שאעזור?" לפני שאת/ה מגיב/ה.$b$, $b$אל תפתח/י תגובה ב"כן, אבל" או "גם לי". אלה דלתות סגורות.$b$, $b$בן/בת הזוג שלך אומר/ת ספונטנית 'תודה שהקשבת לי' — בלי שביקשת אישור.$b$
)
ON CONFLICT (category_id, slug) DO UPDATE SET
  title_he              = EXCLUDED.title_he,
  body_he               = EXCLUDED.body_he,
  task_he               = EXCLUDED.task_he,
  sort_order            = EXCLUDED.sort_order,
  is_active             = true,
  audience              = EXCLUDED.audience,
  stage                 = EXCLUDED.stage,
  source_attribution_he = EXCLUDED.source_attribution_he,
  source_attribution_en = EXCLUDED.source_attribution_en,
  expert_insight_he     = EXCLUDED.expert_insight_he,
  common_mistakes_he    = EXCLUDED.common_mistakes_he,
  metaphor_he           = EXCLUDED.metaphor_he,
  measurement_he        = EXCLUDED.measurement_he,
  do_this_week_he       = EXCLUDED.do_this_week_he,
  dont_this_week_he     = EXCLUDED.dont_this_week_he,
  progress_marker_he    = EXCLUDED.progress_marker_he,
  updated_at            = now();

-- Row #3: שלב 1 · תקשורת זוגית · ביקורת מול תלונה — להפריד את המעשה מהאדם
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-003',
  $b$ביקורת מול תלונה — להפריד את המעשה מהאדם$b$,
  $b$ג'ון גוטמן מצא שארבעה דפוסי תקשורת מנבאים בדיוק של 90% האם זוגיות תסתיים בגירושין. הוא קרא להם 'ארבעת הסוסים': ביקורת, בוז, מגננה, והקפאה. הביקורת היא הראשון — והיא דלת הכניסה לשלושת האחרים.

ההבדל בין ביקורת לתלונה הוא דק אבל קריטי. תלונה: "אתה לא הוצאת אשפה היום, ואני זקוקה ל...". ביקורת: "אתה אף פעם לא חושב על אף אחד חוץ מעצמך". התלונה היא על מעשה. הביקורת היא על האופי. שתיהן יכולות להישמע כועסות — אבל רק אחת פותחת שיחה. השנייה גורמת לבן/בת הזוג להיכנס למגננה.

למה אנחנו מבקרים? בדרך כלל זה תוצאה של תלונות שלא טופלו. אם ביקשת שלוש פעמים שיוציאו את האשפה ושום דבר לא קרה, בפעם הרביעית קל לפרוץ ל"אתה אף פעם לא...". זו התלונה שצברה כעס. הפתרון הוא לא לדחוס תלונות — אלא להעלות אותן מוקדם, באומץ ובלי דרמה.

גוטמן מציע פורמולה: "אני מרגיש/ה X, על Y, ואני זקוק/ה ל-Z". "אני מרגישה לבד כשאתה במחשב כל הערב, ואני זקוקה לחצי שעה איתך לפני השינה". זה לא מאשים — זה משתף. זה לא דורש — זה מבקש. זה לא דן — זה מציע.

הקושי הוא שכשאנחנו פגועים, המוח שלנו רוצה לפגוע בחזרה. הביקורת היא לעיתים נשק — וכשאנחנו מנסחים אותה כתלונה, אנחנו מוותרים על הנשק. זה דורש בגרות רגשית. אבל זה גם החילוף היחיד שעובד לאורך זמן: ביקורת בונה אסירים, תלונה בונה שותפים.

טיפ פרקטי: לפני שאת/ה מנסח/ת תלונה קשה, חכה/חכי 20 דקות. כתוב/י אותה. קרא/י אותה בקול לעצמך. שאל/י: 'אם הוא/היא היו אומרים לי את זה, איך הייתי מרגיש/ה?'. אם התשובה היא 'הייתי מתקפל/ת', נסה/י לנסח שוב. גוטמן מצא שהתחלה רכה ("Soft Startup") קובעת את הצלחת השיחה ב-96% מהמקרים.$b$,
  $b$כתבו כל אחד שלוש 'ביקורות' שאמרתם השבוע על בן/בת הזוג. נסו לתרגם אותן לתלונה — מה הייתה ההתנהגות הספציפית? מה הצורך שלא נענה? נסחו אחת מחדש בנוסחת "אני" — "כשקרה X, הרגשתי Y, ואני זקוק/ה ל-Z".$b$,
  10003, 0, true, 'both',
  1,
  $b$John Gottman, Four Horsemen of the Apocalypse$b$, $b$John Gottman, Four Horsemen of the Apocalypse$b$,
  $b$גוטמן מבחין: תלונה היא על התנהגות ספציפית ("שכחת להוציא אשפה"). ביקורת היא על האופי של בן/בת הזוג ("אתה תמיד שוכח, אתה בנאדם לא אמין"). הראשונה בריאה. השנייה — אחת מארבעת הסוסים האפוקליפטיים שמנבאים גירושין.$b$, $b$1) להתחיל משפט ב"אתה תמיד" / "את אף פעם". 2) להפוך טעות אחת לאבחנה אישיותית. 3) לאסוף תלונות שבועיות ולשפוך הכל בריב אחד. 4) לתת ביקורת כשמרגישים פגועים, מתוך תקווה שזה ירפא — ההפך הוא הנכון.$b$, $b$תלונה היא חץ שמכוון לחלון שצריך לתקן. ביקורת היא חץ שמכוון לאדם עצמו — והוא בורח, או שולף חץ משלו.$b$,
  $b$ספרו השבוע: כמה פעמים פתחתם משפט ב"אתה תמיד" / "את אף פעם".$b$, $b$תרגל/י את הפורמולה: "אני מרגיש/ה X, כש-Y, ואני צריך/ה Z". פעם אחת ביום, גם בדברים קטנים.$b$, $b$אל תאסוף/י תלונות. כל פעם שצף משהו — דבר/י תוך 24 שעות.$b$, $b$בן/בת הזוג שלך לא נכנס/ת למגננה כשאת/ה מעלה משהו. השיחה ממשיכה, לא נסגרת.$b$
)
