-- Row #4: שלב 1 · תקשורת זוגית · בוז — הרעל שמסכן את הזוגיות יותר מכל
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-004',
  $b$בוז — הרעל שמסכן את הזוגיות יותר מכל$b$,
  $b$כשגוטמן צופה בזוגות בלאב לאב, הוא מחפש מיקרו-הבעות בפנים — שניות ספורות שחושפות מה הזוג חושב באמת. הבוז מתבטא במנשא בלשון, חיוך עקום, גלגול עיניים, או טון של 'אתה רציני?'. הוא יכול לבוא בתחפושת של הומור — אבל המוח של בן/בת הזוג קורא אותו נכון.

מה ההבדל בין כעס לבוז? כעס אומר "אני פגוע, ואני רוצה שתבין". בוז אומר "אתה פחות ממני". כעס מצריך תיקון. בוז מצריך ניתוק. ולכן בוז הוא הכי קטלני — הוא לא בא לפתור, הוא בא לחתום על נחיתות.

מהיכן הבוז מגיע? בדרך כלל מתסכול שלא טופל לאורך זמן. אם רגשתי לא נשמע/ת חודשים, לא רק שכעסתי — אני התחלתי לראות אותך כפחות. הבוז הוא הפיזיולוגיה של 'נגמר לי הכבוד'. וברגע שאיבדנו כבוד, יקח הרבה יותר מאשר שיחה אחת לבנות אותו מחדש.

גוטמן מצא שהאנטידוט לבוז הוא תרבות של הערכה והכרה — מה שהוא מכנה 'יחסי 5:1'. בזוגיות בריאה, על כל אינטראקציה שלילית יש חמש חיוביות. לא בריאה ולא רומנטית — אלה רגעים פשוטים: 'תודה שהוצאת את הזבל', 'נראה לי שעשית עבודה מצוינת בפגישה', 'אני אוהבת איך שאתה צוחק'. אלה לא חמש לרגע — חמש למאזן הכולל.

אם זיהיתם שיש בוז ביחסים שלכם, אל תיבהלו — זה לא אבחנה סופית. אבל זה דורש פעולה. הצעד הראשון הוא לעצור את הזרם: לא לאפשר לעצמכם יותר לעלוב, גם בקלילות, גם בהומור. השני הוא להתחיל מודע באמירות הוקרה — אפילו על דברים שכבר ברורים. השלישי הוא לזהות את התסכול שמתחת — ולטפל בו ישירות, בשיחה אמיתית.

אם הבוז כבר מקובע — שווה לבקש עזרה מקצועית. גוטמן מדגיש: זה אחד הסימנים הברורים שזוג זקוק לטיפול לפני שהזוגיות עצמה נשחקת מתחת לרגליים. אבל אם תופסים אותו מוקדם, הוא הפיך — והעבודה עליו תחזיר משהו עמוק לזוגיות: כבוד הדדי.$b$,
  $b$ערכו רשימה אישית, בנפרד: באילו רגעים אתם מרגישים מעט עליונים על בן/בת הזוג? באילו תחומים? (כסף, חינוך, מקצועיות, רגישות, גוף) — וזיהו: איזה מהם נדבק לתקשורת היומיומית. שתפו את הרשימה זה עם זה — מתוך כוונה לשיפור, לא להאשמה.$b$,
  10004, 0, true, 'both',
  1,
  $b$John Gottman, Four Horsemen of the Apocalypse$b$, $b$John Gottman, Four Horsemen of the Apocalypse$b$,
  $b$מתוך ארבעת הסוסים, בוז הוא המסוכן ביותר. הוא מתבטא בעיניים מתגלגלות, לעג, ציניות, השוואה משפילה. זוגות עם בוז גבוה לא רק נפרדים — הם גם חולים יותר פיזית. בוז פוגע במערכת החיסון של בן/בת הזוג, מילולית.$b$, $b$1) להניח שלעג קליל הוא 'הומור'. 2) לחשוב על בן/בת הזוג כעל אדם פחות ממך. 3) להחיל סטנדרטים שונים — מותר לי לטעות, לא לו/ה. 4) להשתמש בכינויים מזלזלים ('הוא בייבי', 'היא דרמטית') גם כשהיא/הוא נוכח/ת.$b$, $b$בוז הוא חומצה — הוא לא רק שורף את הרגע, הוא מאכל את הקיר של הזוגיות עצמה. אפילו טיפות קטנות חוזרות יוצרות חור.$b$,
  $b$השבוע: כמה פעמים גלגלתם עיניים בנוכחות בן/בת הזוג? כמה פעמים אמרתם משפט בטון מתנשא?$b$, $b$אמור/אמרי לבן/בת הזוג שלך 5 דברים שאת/ה מעריך/ה בהם השבוע — קונקרטיים, לא כלליים.$b$, $b$אל תרשה/י לעצמך 'הומור' שהוא בעצם לעג. גם פעם אחת, גם בחברים.$b$, $b$אתם מוצאים את עצמכם משבחים זה את זה ספונטנית, גם בלי תרגיל.$b$
)
