-- Row #6: שלב 1 · תקשורת זוגית · הקפאה רגשית — כשבן/בת הזוג נסגר/ת
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-006',
  $b$הקפאה רגשית — כשבן/בת הזוג נסגר/ת$b$,
  $b$הקפאה רגשית היא אחד הדפוסים הכי מתסכלים בזוגיות — כי היא נראית כמו אדישות. אבל גוטמן מצא משהו מפתיע: כשהוא חיבר את המקפיאים למוניטור דופק, הם היו במצב של היפר-אקטיבציה פיזיולוגית. דופק 110, נשימה רדודה, הזעה. מבחוץ — שקטים. מבפנים — סופה.

ההקפאה היא תוצאה של 'הצפה' (Flooding) — כשמערכת העצבים נכבשת על ידי מתח מעבר ליכולת העיבוד. במצב הזה, המוח לא יכול לעבד מילים מורכבות, להבין כוונות, או לנסח תגובה רציונלית. הגוף עובר לאופן הישרדות — להקפיא, להיעלם, או להירדם פנימית.

בעיקר גברים נמצאים במצב הזה לפי המחקר — סף ההצפה שלהם נמוך יותר. כשהאישה לוחצת 'תדבר איתי!', היא חושבת שאת/ה מתחבא/ת. הוא — הגוף שלו פשוט לא מסוגל. הזוגיות נכנסת לדינמיקה הרסנית: היא לוחצת יותר, הוא נסגר יותר, היא נואשת יותר, הוא יוצא מהבית. אף אחד לא רוצה את זה.

הפתרון מתחיל מהבנה: הקפאה היא לא ויתור על הזוגיות — היא בקשה אילמת לזמן. ואם תכבדו את הזמן הזה, תקבלו את בן/בת הזוג חזרה. גוטמן ממליץ על 'הפסקה מובנית': כשמישהו מבקש להפסיק, שניכם מבטיחים לחזור. לא 'אנחנו לא מדברים יותר היום' — אלא 'בעוד 30 דקות אנחנו ממשיכים, בלי לבעוט'.

במהלך 30 הדקות, הגוף צריך להתאוש. וזה לא קורה אם ממשיכים בריב בראש. גוטמן מצא שהדרך היחידה להוריד דופק היא הסחת דעת — קריאה, מוזיקה, הליכה, מקלחת. לא 'איך אני אטיח בו את התשובה הבאה'. אם נשארים בלולאה הריבית, הגוף לא חוזר ל-baseline.

אחרי 20 דקות, רוב האנשים שונים. הם יכולים לחזור לשיחה לא בתוך הנשק, אלא בתוך הסקרנות. לפעמים הריב נראה אחרת — לפעמים הם מבינים שהיה יותר על קוד פנימי מאשר על העובדה שמדברים עליה. ההקפאה הופכת מאיום לכלי — לא דרך להיעלם, אלא דרך לחזור עם נוכחות מלאה.$b$,
  $b$הסכימו על קוד-לקוד-עצירה: מילה או סימן שכל אחד מכם רשאי להוציא כשהוא/היא מרגיש/ה מוצף/ת. ההסכם הוא: כשהקוד יוצא — שניכם נעצרים מיד, יוצאים ל-20 דקות של פעילות מרגיעה (לא לחזור על הריב בראש), וחוזרים בזמן שנקבע מראש.$b$,
  10006, 0, true, 'both',
  1,
  $b$John Gottman, Four Horsemen of the Apocalypse$b$, $b$John Gottman, Four Horsemen of the Apocalypse$b$,
  $b$הקפאה (Stonewalling) היא הסוס הרביעי — כשבן/בת הזוג מפסיק/ה להגיב, מסתכל/ת בטלפון, יוצא/ת מהחדר. גוטמן מצא שזה קורה כשהמערכת הפיזיולוגית מוצפת — דופק מעל 100, חוסר יכולת לעבד מילה. זה לא 'התעלמות מרושעת' — זה הצפה.$b$, $b$1) להאשים את המקפיא/ה ב"חוסר אכפתיות". 2) ללחוץ עוד יותר כשהוא/היא נסגר/ת — מה שמקפיא יותר. 3) לראות את ההקפאה כסיום — היא בקשה לזמן, לא לסיום. 4) לחזור להמשיך מיד אחרי 'הפסקה' של 5 דקות — הגוף לא חזר.$b$, $b$המוח כמו מחשב שמקובע — אם תלחץ/י עוד מקש, הוא לא יגיב מהר יותר. הוא צריך 20 דקות של אתחול.$b$,
  $b$השבוע: כמה פעמים מישהו מכם פשוט נסגר ולא דיבר?$b$, $b$הסכימו על קוד-עצירה. נסו אותו פעם אחת השבוע — גם אם זה לא הכרחי.$b$, $b$אל תרדפו אחרי בן/בת הזוג כשהוא/היא ביקש/ה הפסקה. הזמן ירפא, הלחץ לא.$b$, $b$אתם חוזרים אחרי הפסקה ומסיימים שיחה — לא משאירים אותה תלויה ימים.$b$
)
