-- Row #7: שלב 1 · תקשורת זוגית · מפת אהבה — מה אני באמת יודע/ת על בן/בת הזוג
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-007',
  $b$מפת אהבה — מה אני באמת יודע/ת על בן/בת הזוג$b$,
  $b$אחת התגליות החזקות ביותר של גוטמן היא הקשר בין רוחב 'מפת האהבה' לבין השרידות של הזוגיות. זוגות עם מפות עשירות — שיודעים פרטים קטנים על העולם הפנימי של בן/בת הזוג — עוברים משברים טוב יותר. למה? כי מפה היא חיבור, וחיבור הוא חיסון.

מפת אהבה כוללת לא רק עובדות יבשות (שמות חברים, מסעדות מועדפות) — היא כוללת את הרבדים הפנימיים. מה הפחד הכי עמוק שלו/ה? אילו חלומות הוא/היא מחזיק/ה גם כשהם לא ריאליסטיים? מה הקלות בילדות שעיצבו אותו/ה? מי האדם שהוא/היא הכי מעריץ/ה היום? כשהמפה הזו עדכנית, קל לאהוב — כי אנחנו אוהבים אדם אמיתי, לא דמות שדמיינו.

הבעיה היא שאחרי שלוש-חמש שנים, רוב הזוגות מפסיקים לחקור. אנחנו מניחים שאנחנו 'יודעים'. אבל בני אדם משתנים — אנחנו לא אותו האדם שהיינו לפני חמש שנים. אם המפה לא מתעדכנת, אנחנו אוהבים את הצל של מי שהיה — לא של מי שיש.

התרגול הקלאסי של גוטמן הוא 'שאלות מפת אהבה' — 60 שאלות קצרות שזוגות עונים עליהן זה על זה (לא יחד) ואז משווים. הציון לא חשוב — חשובה השיחה שנפתחת אחרי. "לא ידעתי שזה החבר הכי טוב שלך". "לא חשבתי שאתה זוכר את הסיפור הזה מהילדות". כל פתעה היא הזדמנות לקרבה.

תרגול יומיומי: 'שאלת המפה היומית'. פעם ביום, שאל/י שאלה אחת על העולם הפנימי של בן/בת הזוג שאת/ה לא יודע/ת את התשובה אליה. "מי גרם לך לצחוק היום?". "מה הרגיז אותך הכי הרבה השבוע?". "איזה חלום אתה לא חולם בקול אבל היית רוצה?". התשובות לא חייבות להיות עמוקות — אבל השאלה בעצמה היא מסר: 'אני עוד מסקרן אותך'.

מפת אהבה היא אחד הדברים הכי לא רומנטיים-נשמעים — אבל גם אחד המעצימים-רומנטית-בפועל. זוגות שמכירים זה את זה לעומק לא רק מתיירים מעצמם — הם מרגישים שהם נראים. וזה התנאי הבסיסי לאהבה ארוכת טווח.$b$,
  $b$בלי לבדוק טלפונים — נסו לענות על כל אחת מהשאלות הבאות על בן/בת הזוג: שני חברים שהוא/היא הכי אוהב/ת בעבודה? איזה חלום הוא/היא חולם/ת אבל לא דיבר/ה עליו לאחרונה? מה הכי הלחיץ אותו/ה השבוע? מה האירוע מהילדות שהוא/היא הכי מתגעגע/ת אליו? השוו תשובות.$b$,
  10007, 0, true, 'both',
  1,
  $b$John Gottman, Love Maps$b$, $b$John Gottman, Love Maps$b$,
  $b$גוטמן מגדיר 'מפת אהבה' כמרחב המנטלי שיש לי על העולם הפנימי של בן/בת הזוג: שמות חברים, פחדים, חלומות, חוויות מכוננות, פצעים פתוחים. זוגות מצליחים מעדכנים את המפה ברציפות. זוגות בקושי — המפה שלהם קפואה משנה 1.$b$, $b$1) לחשוב שאחרי 5 שנים 'יודעים הכל'. 2) להניח שאתם אותו אדם שהיינו אז. 3) לדבר רק על נושאים פרקטיים (לוגיסטיקה, ילדים, כסף) ולא על עולם פנימי. 4) להפסיק לשאול שאלות — כי 'אני יודע את התשובה'.$b$, $b$מפת אהבה היא כמו מפה של עיר חיה. אם לא חידשת אותה 3 שנים, אתה תלך לבית קפה שכבר נסגר.$b$,
  $b$השבוע: כמה פעמים שאלתם שאלה מסקרנת על העולם הפנימי שלו/ה?$b$, $b$שאל/י שאלה אחת ביום על העולם הפנימי של בן/בת הזוג — לא לוגיסטית.$b$, $b$אל תניח/י שאת/ה יודע/ת. כל פעם שיש 'הנחה', שאל/י לפני.$b$, $b$את/ה גילית השבוע משהו על בן/בת הזוג שלך שלא ידעת — וזה הפתיע אותך.$b$
)
