-- Row #8: שלב 1 · תקשורת זוגית · Bids — בקשות זעירות לחיבור שאנחנו מפספסים
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-008',
  $b$Bids — בקשות זעירות לחיבור שאנחנו מפספסים$b$,
  $b$ב-Love Lab של גוטמן, חוקרים סופרים מאות אירועים זעירים בכל יום: בקשות זעירות לחיבור. גוטמן קרא להם Bids. "איזה יום", "מצאתי משהו מצחיק", "בא לי קפה" — כל אחד מהם הוא קריאה רכה: 'אתה איתי?'.

התשובה ל-bid יכולה להיות שלוש: (1) Toward — להתחבר, להפנות מבט, להגיב. (2) Away — להתעלם, להמשיך לעשות מה שעשיתי. (3) Against — לדחות בעצבנות ("אני באמצע משהו!"). גוטמן מצא שזוגות שנשארו ביחד 6 שנים אחרי הניסוי הגיבו ב-toward ל-86% מה-bids. אלה שנפרדו — רק 33%.

הסיפור הזה מטלטל. כי 86% לעומת 33% הוא לא הבדל ברגעים גדולים — הוא הבדל באלפי רגעים זעירים שאיש לא זוכר. הזוגיות נשחקת או נבנית באוסף הקטנטן הזה — לא ברגעי דרמה.

למה אנחנו מפספסים bids? בעיקר כי החיים מהירים. אנחנו במחשב, בטלפון, בעבודה, בילדים. ה-bid נשמע 'לא דחוף'. אבל בן/בת הזוג קורא/ת את ההתעלמות החוזרת כ'אני לא חשוב/ה'. ועם הזמן, הוא/היא מפסיק/ה לנסות. וזו השעון של ניתוק זוגי.

הפתרון פשוט אבל דורש מודעות: לזהות bids ולהגיב. לא להגיב באופן מושלם — סתם להגיב. "אה, מה הצחיק אותך?". "כן, גם אני אוהב את השיר הזה". "איזה יום הוא יום עם איזה דבר ספציפי?". המקלחת הקטנה הזו של תשומת לב היא הדבק של הזוגיות.

תרגול: בכל פעם שאת/ה שומע/ת את שמך, או שבן/בת הזוג נכנס/ת לחדר, או אומר/ת משהו ספונטני — נסה/י לראות את זה כ-bid. הפנה/י מבט. תן/י לפחות תגובה אחת. אם את/ה באמצע משהו דחוף, אמור/אמרי 'תן/י לי שתי דקות, אני רוצה לשמוע'. זה גם תגובה — וזה תקף.

המודעות הזאת לבדה משנה זוגיות תוך שבוע. כי רוב הזוגות לא מתרגלים אנטי-אהבה — הם פשוט עיוורים ל-bids. כשהם רואים אותם, הם רוצים לענות. הזוגיות הופכת מקצב של החמצות — לקצב של חיבורים זעירים, ועקביים.$b$,
  $b$במשך שבוע, שניכם מסכמים בכל ערב: כמה bids זיהיתם מבן/בת הזוג היום? איך הגבתם — בפנייה (toward), בהתעלמות (away), או בדחייה (against)? אין מטרה לציון מושלם — המטרה היא להגביר מודעות.$b$,
  10008, 0, true, 'both',
  1,
  $b$John Gottman, The Relationship Cure$b$, $b$John Gottman, The Relationship Cure$b$,
  $b$Bid הוא בקשה זעירה לתשומת לב, חיבור או הומור — "תראה את הציפור הזאת בחוץ", "זוכרת את השיר הזה?". גוטמן מצא שזוגות מצליחים מגיבים ל-86% מה-bids. זוגות שנפרדו — רק ל-33%. כל bid שמתפספס הוא ניתוק קטן.$b$, $b$1) להסתכל בטלפון ולא לזהות שב/בת הזוג מנסה ליצור קשר. 2) להגיב 'מממ' בלי להפנות מבט. 3) לחשוב שאם זה לא 'חשוב', אפשר להתעלם. 4) להחזיר רק ב-bids גדולים (יציאה, מתנה) ולפספס את הקטנים.$b$, $b$bid הוא כמו דפיקה רכה בדלת. אם אני לא עונה — האחר לא יחזור עוד הרבה פעמים. לבסוף, הוא יחפש דלת שתיפתח.$b$,
  $b$ספרו: בכמה bids השבוע הסתכלתם בטלפון במקום בבן/בת הזוג?$b$, $b$כל פעם שבן/בת הזוג מנסה/ה ליצור קשר — הפנה/י מבט והגב/הגיבי, גם אם 5 שניות.$b$, $b$אל תהיה/תהיי בטלפון כשבן/בת הזוג נכנס/ת לחדר. הרם/י עיניים לפחות.$b$, $b$את/ה תופס/ת את עצמך מזהה bids גם בלי לחשוב — ומגיב/ה אוטומטית.$b$
)
