-- Row #9: שלב 1 · תקשורת זוגית · ניסיונות תיקון — איך להציל ריב באמצע
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'communication' LIMIT 1),
  'csv-s1-communication-009',
  $b$ניסיונות תיקון — איך להציל ריב באמצע$b$,
  $b$ויכוחים בזוגיות הם בלתי נמנעים — וגוטמן אומר משהו מפתיע: זוגות מצליחים לא רבים פחות מזוגות בקושי. הם פשוט רבים אחרת. אחד ההבדלים החזקים ביותר הוא 'ניסיונות תיקון'.

תיקון הוא כל פעולה שעוצרת את ההסלמה ומחזירה את שני בני הזוג לזכרון 'אנחנו ביחד'. זה יכול להיות חיוך, מילה הומוריסטית, נגיעה ביד, או הצהרה ישירה — "אני באמצע התעצבנות, אבל אני אוהב אותך". התיקון הוא לא הסכמה — הוא הצהרה על קשר.

מה שמדהים הוא ההבדל בין זוגות. בלאב לאב צילמו זוגות בריב. שני הצדדים שלחו תיקונים. אבל אצל זוגות מצליחים, הצד השני קיבל אותם — חייך בחזרה, נשם, ענה ברכות. אצל זוגות בקושי — התיקון נדחה. "אל תצחק עכשיו". "זה לא הזמן". התוצאה: ההסלמה ממשיכה.

למה אנחנו דוחים תיקונים? כי כשאנחנו ברוגז, המוח שלנו רוצה לנצח. תיקון מציע פסק אש — וחלק בנו לא רוצה לעצור. עד שאני 'מנצח/ת', אני לא רוצה להוריד נשק. אבל גוטמן מראה: זוגות שלא מקבלים תיקונים גם 'מנצחים' — וגם נפרדים. ה'ניצחון' הוא הפסד.

התרגול הזוגי הוא בשני שלבים: (1) לזהות שאת/ה רוצה לשלוח תיקון. (2) להסכים מראש שאת/ה תקבל/י תיקון מהשני. הסכמה זו צריכה להיעשות מחוץ לויכוח — בשעה שלווה. "בוא נסכים: אם מישהו מאיתנו אומר 'אני זקוקה לחיבוק' באמצע ריב — שנינו עוצרים, מתחבקים שלוש שניות, ואז ממשיכים". זה לא מבטל את הוויכוח — זה ממסגר אותו.

תיקונים יכולים להיות בלתי מילוליים: מבט מתרכך, צחוק זעיר, יד שמושטת. הם דורשים אומץ — להיות פגיע באמצע ריב — אבל הם משחררים את שני הצדדים מהמלכודת של 'מי צודק'. הם מזכירים: 'אנחנו לא נגד זה את זה. אנחנו אחד מול בעיה'.

בקצרה: זוגות מצליחים לא רבים פחות. הם רבים יותר רך — כי יש להם דרך החוצה.$b$,
  $b$צרו ביחד 'רשימת תיקון' של 5 משפטים שאתם מסכימים שהם 'דגלים לבנים' שלכם — "אני זקוק/ה לחיבוק", "אני לא רוצה להיות צודק/ת — אני רוצה אותך", "בוא נשתה מים". בויכוח הבא, נסה/י להוציא אחד מהם.$b$,
  10009, 0, true, 'both',
  1,
  $b$John Gottman, Repair Attempts$b$, $b$John Gottman, Repair Attempts$b$,
  $b$ניסיון תיקון הוא כל פעולה זעירה שמטרתה להוריד את המתח באמצע ויכוח — חיוך, מילה משעשעת, מגע ביד, אמירה כמו 'אני זקוק/ה לחיבוק'. גוטמן מצא שזוגות מצליחים שולחים תיקונים — וגם מקבלים אותם. זוגות בקושי שולחים, אבל לא מקבלים.$b$, $b$1) להניח שאם בן/בת הזוג נשמע/ת לא רציני/ת באמצע ריב, הוא/היא 'מזלזל/ת'. 2) לדחות תיקון כי "זה לא הזמן לבדיחות". 3) להציע תיקון רק כשמתפרץ — מאוחר מדי. 4) לא להבין שתיקון הוא דווקא רגע של רכות.$b$, $b$תיקון הוא חיבוק קטן באמצע סופה. הוא לא עוצר את הסערה — הוא מזכיר ש'אנחנו אותו צוות, גם בתוך זה'.$b$,
  $b$השבוע: כמה פעמים מישהו מכם ניסה תיקון? כמה פעמים האחר קיבל אותו?$b$, $b$אמור/אמרי לבן/בת הזוג השבוע: "אני רוצה שנסכים על תיקונים. הנה שלי".$b$, $b$אל תדחה/י תיקון רק כי את/ה עדיין כועס/ת. תיקון לא מבטל את הכעס — הוא מציל את הקשר.$b$, $b$אתם רבים לא פחות — אבל הריבים נגמרים מהר יותר וטובים יותר.$b$
)
