-- Row #11: שלב 1 · מיניות ואינטימיות · מפת התשוקה האישית — מה מדליק אותי באמת
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'intimacy' LIMIT 1),
  'csv-s1-intimacy-011',
  $b$מפת התשוקה האישית — מה מדליק אותי באמת$b$,
  $b$אסתר פרל, שכתבה את "Mating in Captivity", מציעה תפיסה מהפכנית: התשוקה אינה תוצאה של חיבור — היא דורשת ניתוק. הקרבה שאנחנו בונים עם בן/בת הזוג בחיי היומיום (אבטחה, נוחות, קביעות) היא אנטיתזה לתשוקה, שדורשת מסתורין, אש, מרחק.

אבל הצעד הראשון לתשוקה אמיתית הוא לא לעבוד על בן/בת הזוג — אלא להכיר את עצמך. רובנו אף פעם לא חקרנו ברצינות מה מדליק אותנו. אנחנו יודעים מה היה ב-22, אבל לא מה ב-42. אנחנו יודעים מה התרבות אומרת, אבל לא מה הגוף שלנו אומר.

פרל שואלת: מתי הרגשת/י את עצמך הכי חי/ה — בלי קשר לסקס? איזה רגע, איזה הקשר, איזה דמות שיחקת? התשוקה האמיתית לא רק במיטה — היא ברגעי שליטה, ברגעי משחק, ברגעי חופש. לדוגמה: מישהי גילתה שהתשוקה שלה התעוררה כשהיא דיברה בקהל. מישהו גילה שהתשוקה שלו ערה כשהוא יוצר משהו אמנותי. הסקס הוא ביטוי — לא מקור.

כשאני מכיר/ה את המפה הזו, אני יכול/ה להתחיל להביא אותה לזוגיות. לא כדי שבן/בת הזוג יבצע/תבצע אותה — אלא כדי לדעת לבקש את התנאים. "כשאני מתלבש/ת לפני יציאה ואת/ה מסתכל/ת עליי בעיניים מסוימות — זה מדליק אותי". "כשאני מספר/ת על משהו שאני נלהב/ת ממנו ואת/ה מקשיב/ה ברצינות — זה מעורר אותי". זו לא בקשה לסקס — זו מפת תנאים לתשוקה.

פרל מעירה שזה מאיים על רוב הזוגות. כי במקום לחכות שהתשוקה 'תקרה', הם נדרשים לקחת אחריות. וזה דורש פגיעות — להגיד "אני רוצה X", ולסכן ש-X לא יקרה. אבל בלי לקיחת האחריות הזו, התשוקה דועכת — ואז שני הצדדים מאשימים זה את זה.

התרגיל הראשון בזוגיות תשוקתית הוא לא 'בוא נשתפר במיטה' — אלא 'בוא נכיר את עצמנו'. תנו זמן לעצמכם. כתבו ביומן. דמיינו. הקראו ספרות. אחרי שהמפה ברורה, חזרו אחד לשני — לא לבקש, אלא לשתף. וזה כבר רומן.$b$,
  $b$כתוב/י לעצמך, בנפרד, רשימה: 5 רגעים בחיים בהם הרגשתי תשוקה אמיתית — לא מאהבה, מתשוקה. מה היה בכל אחד? מה משותף לכולם? אחרי שכתבתם, שתפו זה את זה — בלי שיפוט, בלי 'למה לא איתי'. רק להכיר את המפה של השני.$b$,
  10011, 0, true, 'both',
  1,
  $b$Esther Perel, Mating in Captivity$b$, $b$Esther Perel, Mating in Captivity$b$,
  $b$פֶּרֶל מבחינה: רובנו לא יודעים מה מדליק אותנו. אנחנו יודעים מה היה בעבר. תשוקה אמיתית מתחילה מהיכרות עצמית — לא מהאחר. לפני שאני יודע/ת לבקש, אני צריך/ה לדעת מה אני רוצה.$b$, $b$1) להניח שאם הייתה תשוקה ב-3 השנים הראשונות, היא 'אמורה' להישאר. 2) לחכות שבן/בת הזוג ידליק/תדליק אותי במקום לחפש בעצמי. 3) להתבייש בפנטזיות שלא תואמות את ה'תפקיד' שאני משחק/ת בזוגיות.$b$, $b$תשוקה היא כמו אש פנימית. בן/בת הזוג יכול/ה להוסיף עצים — אבל את האש אני מחזיק/ה בעצמי.$b$,
  $b$השבוע: כמה פעמים זיהית/ה רגע של תשוקה — גם בלי שזה הוביל לסקס?$b$, $b$כתוב/י השבוע 5 רגעים בחיים שבהם הרגשת תשוקה אמיתית. מה משותף להם.$b$, $b$אל תניח/י שבן/בת הזוג שלך אמור/ה לדעת מה מדליק אותך. את/ה רק עכשיו לומד/ת.$b$, $b$את/ה מבקש/ת תנאי לתשוקה — לא דורש/ת תוצאה.$b$
)
