-- Row #12: שלב 1 · מיניות ואינטימיות · תשוקה ספונטנית מול תשוקה תגובתית
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'intimacy' LIMIT 1),
  'csv-s1-intimacy-012',
  $b$תשוקה ספונטנית מול תשוקה תגובתית$b$,
  $b$אמילי נגוסקי, חוקרת מין מאוניברסיטת אינדיאנה, גילתה אחד הממצאים שמשנים זוגיות: יש שני סוגי תשוקה. תשוקה ספונטנית — קמה מאליה, ללא טריגר חיצוני. אני יושב/ת באוטובוס ופתאום רוצה. תשוקה תגובתית — מתעוררת רק בתגובה לגירוי: מגע, מילה, מבט, ריח.

המחקר של נגוסקי מצא ש-15% מהנשים הן בעיקר ספונטניות, 30% הן תגובתיות, וכ-55% הן תערובת. אצל גברים המספרים הפוכים — רוב גדול ספונטני. הבעיה: התרבות מציגה רק תשוקה ספונטנית כ'נורמלית' — וזוגות חושבים ש'אם אין לי רצון מיידי, יש לי בעיה'.

אין בעיה. יש סוג. ההבדל הוא קריטי. אם אני מצפה לתשוקה ספונטנית כדי להתחיל סקס, ואני תגובתי/ת — אני אחכה לעולם. הגוף שלי לא נדלק לפני שמשהו מדליק אותו. ואם בן/בת הזוג שלי מצפה לרגעי 'אני רוצה' שאני מציע/ה — הוא/היא יחכה גם הוא/היא לעולם, וההמתנה תהפוך לטינה.

הפתרון הוא מודעות הדדית. כל אחד מבן הזוג מבין את הסוג של עצמו ושל השני. אם אני תגובתי/ת, אני מסכים/ה לנסות 5 דקות של מגע גם בלי 'תשוקה ספונטנית' — כי אני יודע/ת שהיא תופיע. אם בן/בת הזוג שלי תגובתי/ת, אני לא לוקח/ת 'בא לי לישון' כדחייה — אני מציע/ה לחמם, בעדינות, בלי לחץ.

נגוסקי מציעה דימוי של 'אקסלרטור ובלם'. כל אחד מאיתנו עם רגישות שונה לכל אחד מהם. אצל אנשים תגובתיים, האקסלרטור איטי — אבל הוא דווקא רגיש מאוד לבלמים. סטרס בעבודה, רגש לא נעים, חדר חם מדי — כל אחד מהם בלם. בלי להוריד בלמים, האקסלרטור לא יוכל לעבוד.

התרגול הזוגי הוא: להוריד בלמים לפני להאיץ. 5 דקות חיבוק ביום, מקלחת חמה, אווירה רגועה, שיחה בלי סטרס — כל אלה מורידים בלמים. כשהבלמים נמוכים, הספונטניות חוזרת — והיא לא נדרשת. הגוף פשוט עונה. וזה הסקס הכי טוב — לא הראשון של היחסים, אלא זה של הזוגיות הבוגרת.$b$,
  $b$שיחה זוגית: כל אחד מסביר את הסוג שלו. מי 'ספונטני' יותר? מי 'תגובתי'? איך זה מתבטא? איך זה גרם לאי-הבנות בעבר? קבעו ניסוי: השבוע, ה'ספונטני' מציע, ה'תגובתי' לא דוחה אוטומטית — אלא נותן 5 דקות לראות אם הגוף עונה.$b$,
  10012, 0, true, 'both',
  1,
  $b$Emily Nagoski, Come As You Are$b$, $b$Emily Nagoski, Come As You Are$b$,
  $b$נגוסקי מבחינה בין שני סוגי תשוקה: ספונטנית (קמה מאליה, 'אני רוצה') ותגובתית (מתעוררת בתגובה לגירוי). 70% מהנשים הן 'תגובתיות' בעיקר. רוב הזוגות לא יודעים את ההבדל — וחושבים שתשוקה תגובתית = 'אין לי תשוקה'.$b$, $b$1) לחכות לתשוקה ספונטנית כדי להתחיל סקס. 2) לחשוב שאם אין רצון מיידי, אין רצון בכלל. 3) להתבייש שצריך 'להתחמם'. 4) להכריח את עצמך — מה שמייצר אנטי-תשוקה.$b$, $b$תשוקה ספונטנית כמו תפוח שנופל מהעץ. תשוקה תגובתית — צריך לקטוף אותו. שניהם תפוחים. שניהם טעימים.$b$,
  $b$השבוע: כמה פעמים הצעתם או נענו לסקס שהתחיל מתגובתיות, לא מספונטניות?$b$, $b$אם את/ה תגובתי/ת — נסה/י השבוע 5 דקות של מגע גם בלי 'בא לי' מיידי. שים/י לב מה קורה.$b$, $b$אל תאשים/י את עצמך או את בן/בת הזוג ב'אין תשוקה'. הסוג שונה — לא חסר.$b$, $b$אתם מתחילים אינטימיות בלי לחכות ל'הרגע המושלם' — והוא מגיע תוך כדי.$b$
)
