-- Row #13: שלב 1 · מיניות ואינטימיות · סקס מתחיל הרבה לפני המיטה
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'intimacy' LIMIT 1),
  'csv-s1-intimacy-013',
  $b$סקס מתחיל הרבה לפני המיטה$b$,
  $b$אסתר פרל מספרת שכשהיא שואלת זוגות 'מתי המיניות מתה אצלכם?' — רובם מצביעים על ה-9 בערב. אבל הם טועים בכתובת. המיניות לא מתה ב-9 — היא נחנקה לאט במהלך היום. הסקס מתחיל בשבע, כשמתעוררים, ונמשך בנשיקה הקצרצרה לפני שיוצאים, ובמסרון הראשון, ובמבט בארוחת ערב.

הבעיה היא שהיום שלנו לא מקדם אינטימיות — הוא מנגב אותה. אנחנו רצים בין משימות, מתאמים לוגיסטיקה דרך הטלפון, מסתכלים זה על זה רק כשמשהו לא בסדר. בערב, אנחנו 'מצפים' שהמיניות תקפוץ ממקום שלא טיפחנו אותו. וזה לא קורה.

גוטמן מציע מודל פרקטי: 'הקלים הקטנים של היום' — 6 רגעים יומיים שבונים אינטימיות. (1) פרידה בבוקר עם נשיקה של 6 שניות (לא 6 רגעים — 6 שניות באמת). (2) חיבור בטלפון או הודעה במשך היום. (3) ברכת שלום בחזרה הביתה — להפנות מבט, לא רק 'היי' מהמטבח. (4) שיחת הקצב של 20 דקות. (5) רגע פיזי — חיבוק, ליטוף, ישיבה ביחד. (6) פרידה לקראת השינה — מילה, נשיקה, מבט.

כל אחד מאלה לוקח דקה. שש דקות סך הכל. אבל הם בונים את הקרקע המינית של הזוגיות. בלעדיהם, הזוגיות בלילה היא 'מנהל מול עובד' — ואז מתפלאים שאין תשוקה. המודל לא מצליח להציע מיניות אם המבנה היומי לא מאפשר אותה.

פרל מוסיפה זווית שונה — של מסתורין. הסקס מצטבר גם מתוך מה שעוד לא נאמר. "שמרי בלב מה אנחנו עומדים לעשות כשהילדים נרדמים" — מסר כזה בצהריים בונה ערב. מסתורין הוא לא הסתרה — הוא בנייה של ציפייה. וציפייה היא הדלק של תשוקה.

התרגיל הזוגי השבוע: שני זוגות מסרונים אינטימיים ביום. לא תמונות, לא 'בא לי' חזק. רק ציון של נוכחות — "חושב עלייך עכשיו". "הריח שלך עוד פה". "בא לי לראות אותך". הזוגיות תהפוך מ'מטפלים בילדים ביחד' ל'אוהבים שגם מנהלים בית'.$b$,
  $b$שלחו זה לזה לפחות 3 הודעות במהלך היום: לא לוגיסטיות, לא ילדים. רק 'אני חושב עליך', 'הריח שלך עוד עליי', 'בא לי לראות אותך'. שימו לב לערב — הוא ירגיש אחרת.$b$,
  10013, 0, true, 'both',
  1,
  $b$Esther Perel + John Gottman$b$, $b$Esther Perel + John Gottman$b$,
  $b$פרל ובנגוסקי מסכימים: הסקס שמתחיל ב-21:00 בחדר השינה — נקבע ב-9:00 בבוקר. זה מצטבר במהלך היום מהמבטים, המגעים הקטנים, מילות ההערכה, או — להיפך — מההזנחה.$b$, $b$1) לחשוב שסקס הוא אירוע 'נפרד' מיתר היום. 2) להאשים את בן/בת הזוג בלילה על הזנחה של היום. 3) לחכות לאווירה במקום לבנות אותה. 4) לחשוב ש'הקדמה' זה רק 5 דקות לפני.$b$, $b$סקס הוא כמו בישול ארוך — אם לא התחלת בבוקר, אי אפשר להגיש בלילה. החומר הגלם הוא היום עצמו.$b$,
  $b$השבוע: כמה פעמים שלחת הודעה אינטימית במהלך יום עבודה?$b$, $b$שלחו לפחות 3 הודעות אינטימיות במהלך היום. נסו 'נשיקת 6 השניות' לפחות פעמיים בשבוע.$b$, $b$אל תחכו לערב כדי 'להתחיל'. הערב הוא רק התוצאה של היום.$b$, $b$אתם מרגישים מחוברים גם בערבים שלא מסתיימים בסקס.$b$
)
