-- Row #14: שלב 1 · מיניות ואינטימיות · ארוטיקה מול מיניות — שני שדות שונים
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'intimacy' LIMIT 1),
  'csv-s1-intimacy-014',
  $b$ארוטיקה מול מיניות — שני שדות שונים$b$,
  $b$אסתר פרל פותחת את ספרה במשפט שמטלטל זוגות: "רוב הזוגות מבקשים יותר סקס. אבל מה שחסר להם הוא לא סקס — אלא ארוטיקה". ההבחנה הזו פותחת דלת לזוגיות חדשה.

מיניות, אומרת פרל, היא הפעולה — מה הגוף עושה. ארוטיקה היא ההרגשה — מה הנפש עושה כשהיא מרגישה רצויה, מסתורית, מטרידה. בזוגיות בריאה, הם הולכים יחד — אבל הם לא אותו הדבר. אפשר לעשות סקס ללא ארוטיקה (סקס 'רגיל', שגרתי, בלי להבים). ואפשר לחיות ארוטיקה ללא סקס (מבט, נגיעה זריזה, מסרון מסעיר).

הבעיה ברוב הזוגות אחרי 5 שנים היא לא חוסר סקס — היא חוסר ארוטיקה. הסקס יכול להיות עדיין שם, אבל בלי האש. בלי הציפייה. בלי התחושה ש'משהו עומד לקרות'. וזה מה שהופך מיטה לחובה ולא להזמנה.

איך בונים מחדש ארוטיקה? פרל מציעה כמה מפתחות: (1) מסתורין — לא לדעת הכל אחד על השני. לתת מקום לרבדים שעוד לא נחקרו. (2) מרחק — רגעים שבהם אנחנו לא ביחד מאפשרים תשוקה כשנפגשים. (3) משחק — רוב הזוגות מפסיקים לשחק. הם מתחילים 'להיות אחראיים'. אבל ארוטיקה היא לא רצינית — היא משחקית. (4) מרחב פנטזיה — לאפשר לעצמנו, ולשני, לחלום בלי שיפוט.

אחת ההמלצות המעשיות של פרל: "תרגיל ההזמנה". במקום לבקש סקס, צרו הזמנה ארוטית — אווירה שמרמזת בלי להגדיר. שיר ספציפי, ריח, פריט לבוש. הזוגיות מקבלת גוון של 'משהו עומד לקרות' — וגם אם בסוף לא קורה כלום, הערב היה ארוטי.

ולפעמים, הארוטיקה הכי חזקה היא בדיוק ברגעים שלא מסתיימים בסקס. נשיקה ארוכה במטבח, חיבוק עם נשימה משותפת, מבט של 20 שניות בלי מילה. הם בונים 'נכס ארוטי' — שיחזור ביום אחר, יום שני שלישי, וייתן לזוגיות אש שלא תיכבה.$b$,
  $b$בלי לתכנן סקס: צרו רגע ארוטי השבוע. לבוש/י משהו שגורם לך להרגיש מחושב/ת. שב/י על בן/בת הזוג מהצד. הסתכלו זה בעיני זה במשך 30 שניות. אל תיגעו אחר כך. תנו לרגע הזה להישאר ארוטי — בלי 'לפתור' אותו במיטה.$b$,
  10014, 0, true, 'both',
  1,
  $b$Esther Perel, Mating in Captivity$b$, $b$Esther Perel, Mating in Captivity$b$,
  $b$פרל מבחינה: מיניות (sexuality) היא מה שעושים בגוף. ארוטיקה (eroticism) היא מה שמרגישים בנפש. אפשר לעשות סקס שאינו ארוטי. ואפשר ליצור רגע ארוטי ללא נגיעה. הזוגיות הבריאה זקוקה לשניהם.$b$, $b$1) להחליף ארוטיקה במיניות — והפוך. 2) לחשוב שסקס תמיד ארוטי, או שארוטיקה היא בהכרח מקדימה לסקס. 3) לדחות רגעי ארוטיקה כי 'אנחנו לא הולכים לסקס היום'.$b$, $b$מיניות היא הארוחה. ארוטיקה היא הריח של הבישול. שתיהן מזינות — ולא תמיד באותו זמן.$b$,
  $b$השבוע: כמה רגעים ארוטיים יצרתם, גם אם לא הובילו לסקס?$b$, $b$צרו רגע ארוטי שלא מסתיים בסקס — מבט, נגיעה, מסרון. תנו לו להישאר ארוטי בלבד.$b$, $b$אל 'תפתרו' כל ארוטיקה במיטה. תנו לרגעים להישאר תלויים — זה דלק.$b$, $b$אתם מרגישים את ה'משהו עומד לקרות' גם ביום רגיל — לא רק בלילה ספציפי.$b$
)
