-- Row #18: שלב 1 · מיניות ואינטימיות · כשבן/בת הזוג אומר/ת 'לא הלילה' — אומנות הסירוב הרך
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'intimacy' LIMIT 1),
  'csv-s1-intimacy-018',
  $b$כשבן/בת הזוג אומר/ת 'לא הלילה' — אומנות הסירוב הרך$b$,
  $b$אסתר פרל מציינת שהרגע הכי שביר בזוגיות מינית הוא לא הסקס עצמו — אלא הרגע שלפני. כשאחד מציע, והשני צריך להגיב. הצעות וסירובים. ובדיוק שם, רוב הזוגות מאבדים אחד את השני.

ההצעה היא רגע של פגיעות. אני מציג/ה את הרצון שלי — וצריך/ה להמתין לתשובה. הסירוב, אם הוא קר, נשמע כדחייה אישית. "אני עייפה" קצרה היא לא רק על הלילה — היא קוראה כ'אני לא רוצה אותך'. ואחרי כמה סירובים כאלה, הצד המציע מפסיק להציע. הסקס מת — לא מהיעדר רצון מצידו של מישהו, אלא מתקשורת לקויה.

הפתרון הוא 'סירוב רך' — נוסחה שמכירה בפגיעות של ההצעה ושומרת על הקשר גם כשהתשובה היא לא. הנוסחה כוללת ארבעה אלמנטים: (1) הצהרת אהבה — 'אני אוהב/ת אותך'. (2) סירוב ברור — 'לא הלילה'. (3) הצעת חלופה — 'בא לי שנתחבק / נדבר / נישן בחיבוק'. (4) הזמנה לעתיד — 'מחר אני רוצה אותך' או 'בסוף השבוע נארגן זמן'.

הנוסחה הזו עושה שלושה דברים. ראשית, היא מאשרת את ההצעה — "אני רואה אותך". שנית, היא מבחינה בין הסירוב לדחייה — "אני לא דוחה אותך, אני דוחה את הזמן". שלישית, היא בונה ציפייה — "מחר משהו עומד לקרות". וכל שלושת אלה משמרים את האש, גם בלילה ללא סקס.

מצידו של המציע, האתגר הוא לקבל את הסירוב הרך בלי להעלב. גם אם בלילה אחר זה היה כן, הלילה זה לא — וזה חלק מזוגיות. נגוסקי מזכירה: כל אחד מאיתנו במחזור פיזיולוגי משלו. הגוף לא תמיד מסונכרן. סירוב הוא לא דחייה — הוא רק תזמון.

הזוגיות הבריאה לא בורחת מסירובים — היא יודעת לעשות אותם רכים. ובמין שאחרי, הצדדים יודעים שיש מקום לרצות, ויש מקום לא לרצות, ועדיין להישאר אהובים. וזה בעצמו — מעורר תשוקה.$b$,
  $b$הסכימו על 'נוסחת סירוב רך': כשאחד מכם לא רוצה — אומר/ת "אני אוהב/ת אותך, לא הלילה. בא לי X (חיבוק/ערב יחד/לחבק לפני שינה). מחר/בסוף השבוע אני רוצה אותך". וגם: הסכימו שהסירוב יבוא עם מגע — נשיקה, חיבוק, יד על הלב. לא ניתוק.$b$,
  10018, 0, true, 'both',
  1,
  $b$Esther Perel + Emily Nagoski$b$, $b$Esther Perel + Emily Nagoski$b$,
  $b$סירוב הוא רגע של פגיעות מקסימלית. הסירוב הקשה — "אני עייף/ה" קצר וקריר — הוא אחד הגורמים המרכזיים לקיפאון מיני. סירוב רך, לעומת זאת, יכול לשמור על הקשר ואפילו לבנות ציפייה.$b$, $b$1) להתעלם מהבקשה ולפתוח טלפון. 2) להגיב בעצבנות ('שוב את עייפה?'). 3) לקחת סירוב באופן אישי כתחושת דחייה כוללת. 4) להפסיק להציע אחרי דחייה אחת — וליצור 'מוות מיני שקט'.$b$, $b$סירוב הוא כמו דלת חצי סגורה. אפשר לטרוק אותה — או לתת לה נסיגה רכה ולומר 'מחר אפתח'.$b$,
  $b$השבוע: איך הגעתם לסירובים? קרים? רכים?$b$, $b$אם דחיתם השבוע — נסו את הנוסחה (אהבה + לא + חלופה + עתיד).$b$, $b$אל תדחו בקור או בקצרה. כל סירוב הוא הזדמנות לחיבור.$b$, $b$אתם דוחים יותר ברכות — והאחר לא נפגע, אלא מתחבק וסומך.$b$
)
