-- Row #19: שלב 1 · מיניות ואינטימיות · סקס בזוגיות ארוכת טווח — האש שלא תמה
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'intimacy' LIMIT 1),
  'csv-s1-intimacy-019',
  $b$סקס בזוגיות ארוכת טווח — האש שלא תמה$b$,
  $b$אסתר פרל מספרת שזוגות שמגיעים אליה אומרים: "אנחנו שוב חברים טובים. אנחנו צוות מצוין. אבל המין... המין נעלם". ופרל מסבירה: זה לא במקרה. זה תוצר של הצלחת הזוגיות עצמה. כי תשוקה זקוקה למרחק, מסתורין, וחוסר ודאות — בדיוק מה שזוגיות ארוכת טווח מנסה לסלק.

הבסיס של זוגיות יציבה הוא ביטחון: 'אני יודע/ת מי הוא/היא, אני יודע/ת מה יקרה, אני יודע/ת שלא יעזוב/תעזוב'. ביטחון זה הוא מתנה — אבל הוא גם בולם תשוקה. כי תשוקה היא יצור של 'אני לא יודע מה יקרה'. אז איך אפשר להחזיק שניהם?

פרל מציעה גישה מהפכנית: לא לבחור בין ביטחון לתשוקה — לטפח את שניהם, בנפרד. לבנות 'אזורים של ארוטיקה' בתוך הזוגיות הבטוחה. אזורים שבהם בן/בת הזוג נשאר/ת מסתורי/ת. שבהם יש מסתורין, ציפייה, אי-ידיעה. אלו הם הרגעים שבהם התשוקה גרה.

כיצד? פרל מציעה כמה כלים: (1) פגישה כמו אורחים — ערב שבו כל אחד מגיע מתוך 'מי האחר' ולא מתוך 'מה אני יודע/ת עליו/ה'. (2) שיחות שלא היו עוד — נושאים, חלומות, פנטזיות, פחדים שלא דובר/ה עליהם. (3) פעילויות נפרדות — אני נוסע/ת לסוף שבוע, את/ה נשאר/ת. הפרידה הקצרה מבעירה תשוקה. (4) רגעי תפקיד — להתחפש, לשחק, לדמיין שאנחנו אנשים אחרים. הילד שבזוגות מקדם תשוקה יותר מהמבוגר.

הקושי הוא הפנימי. כי טיפוח אש דורש אומץ — להיות פגיע/ה, להציע משהו לא ברור, להסתכן בכישלון. רוב הזוגות מעדיפים את הביטחון של 'הרגיל' — ואיתו הם מאבדים גם את האש. הזוגיות שמטפחת תשוקה היא לא שגרתית — היא מודעת.

ולמרות הכל, פרל מזכירה: זוגיות בריאה היא לא תשוקה כל יום. היא תשוקה שנכנסת ויוצאת, נחה ומתעוררת. המטרה היא לא 'תשוקה רציפה' — היא 'תשוקה שיודעת לחזור'. וזה דורש זוגות שיודעים לתת מקום לאש לבעור — ולא לכבות אותה ברגע שהיא קצת לא נוחה.$b$,
  $b$תרגיל 'אורח חדש': ערב אחד, התנהגו אחד עם השני כאילו פגשתם הרגע. שאלות חדשות. בגדים שלא הולכים בהם בבית. לא לדבר על ילדים, על מטלות, על העבודה. ראו את בן/בת הזוג כמו ביום הראשון.$b$,
  10019, 0, true, 'both',
  1,
  $b$Esther Perel, Mating in Captivity$b$, $b$Esther Perel, Mating in Captivity$b$,
  $b$פרל מציגה פרדוקס: דווקא הזוגות הקרובים והבטוחים ביותר מאבדים תשוקה. תשוקה דורשת מסתורין, מרחק, לא ידוע — בדיוק מה שזוגיות ארוכת טווח שואפת לנטרל. הפתרון הוא לטפח את הניגוד.$b$, $b$1) לחשוב שתשוקה תחזור 'מאליה' אם רק נוותר על הלחץ. 2) להיכנע ל'סקס שגרה' ולהפסיק לנסות. 3) להאשים את בן/בת הזוג בחוסר אש — במקום לחקור את ההצטמצמות הפנימית. 4) להסתיר פנטזיות מ'בושה' — מה שמסיר אנרגיה ארוטית.$b$, $b$תשוקה כמו אש חיה. בית מסודר וחסום — היא נחנקת. בית עם חלון פתוח — היא בוערת.$b$,
  $b$השבוע: כמה פעמים ראיתם את בן/בת הזוג מתוך 'הרגל' לעומת מתוך 'מסקרנות'?$b$, $b$ערב אחד 'פגישה ראשונה' — בגדים, תוכנית, שיחה — כאילו עוד לא הכרתם.$b$, $b$אל תיכנעו ל'אנחנו ממילא יודעים זה את זה'. תמיד יש עוד מה לגלות.$b$, $b$אתם מצליחים להיות מסתוריים זה לזה — גם אחרי שנים.$b$
)
