-- Row #20: שלב 1 · מיניות ואינטימיות · פנטזיה כחלון לעצמי — לא איום על הזוגיות
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'intimacy' LIMIT 1),
  'csv-s1-intimacy-020',
  $b$פנטזיה כחלון לעצמי — לא איום על הזוגיות$b$,
  $b$ג'ק מורין, פסיכולוג שחקר את הארוטיקה במשך ארבעים שנה, גילה משהו מטלטל: הפנטזיות שלנו אינן רק 'שעשוע'. הן כתב סודי שמספר את מי שאנחנו — את הכאב, את ההשתוקקות, את התשוקה שלא נאמרה.

פרל מתבססת על מורין כשהיא טוענת: שיתוף פנטזיה הוא אחת הדרכים האינטימיות ביותר להכיר את בן/בת הזוג. כי בפנטזיה, אנחנו לא במצב של ביצוע — אנחנו במצב של חופש. אנחנו אומרים לעצמנו 'מה היה קורה אם'. וברגע ששיתפתי, בן/בת הזוג רואה רובד עמוק שלי שאף אחד אחר לא רואה.

אבל רוב הזוגות לא משתפים. למה? פחד. שלוש פחדים: (1) פחד מהתפרשות — שהפנטזיה תיקרא כ'דרישה'. (2) פחד מהתפרשות אישית — שמה שאני פנטזיונל/ת עליו 'מסגיר' משהו רע באישיותי. (3) פחד מהסערה הזוגית — שהפנטזיה תאיים על בן/בת הזוג ותביא לקנאה או דחייה.

הפתרון הוא הסכם זוגי על הפרדה בין 'פנטזיה' ל'תוכנית'. פנטזיה היא דמיון — היא לא חייבת לקרות. שיתוף פנטזיה הוא חשיפה רגשית, לא הזמנת ביצוע. ההסכם הוא: 'אני אספר לך את המעמקים שלי. את/ה לא תפרש/י את זה כ'בקשה'. אנחנו פשוט נכיר זה את זה'.

תרגיל קלאסי של פרל: 'חילופי מכתבי פנטזיה'. כל אחד כותב פנטזיה — לא בהכרח מינית במלוא המובן, אלא דמיון על רגע אינטימי. החליפו דפים. תפקיד הקורא/ת הוא רק לשאול שאלה אחת מסקרנת — 'מה החלק שהכי מעורר אותך?', 'איך הרגשת לכתוב את זה?'. לא הצעות, לא הסכמות לבצע. רק חקירה משותפת.

הקסם של התרגיל: גם אם הפנטזיה לא תבוצע אף פעם, היא הופכת ל'נכס משותף' של הזוגיות. סוד שני בני הזוג שותפים לו. ובסוד הזה — נמצאת אינטימיות שאין במקום אחר.

פרל מסכמת: "זוגות בריאים אינם זוגות ללא פנטזיות. הם זוגות שיודעים מה הפנטזיות של השני — ואוהבים אותו/ה גם בזה".

הפנטזיה היא לא איום. היא בית. וכשבן/בת הזוג נכנס/ת לבית הזה ברוך — האהבה משתנה לתמיד.$b$,
  $b$כל אחד כותב על דף פנטזיה אחת — מילולית, כפי שהיא מופיעה. החליפו דפים. הצד המקבל שואל שאלה אחת בלבד: "מה הצד שמעורר אותך הכי הרבה בזה?". בלי שיפוט, בלי 'נעשה את זה'. רק לדבר על הפנטזיה כסיפור.$b$,
  10020, 0, true, 'both',
  1,
  $b$Esther Perel + Jack Morin, The Erotic Mind$b$, $b$Esther Perel + Jack Morin, The Erotic Mind$b$,
  $b$ג'ק מורין: הפנטזיה היא 'לוח הציורים הנפשי' של כל אחד — מקום שבו הילדות, הפצעים, החלומות וההבטחות נפגשים. שיתוף פנטזיות אינה איום על הזוגיות — היא העמקה. הסכנה האמיתית: פנטזיה במחבוא, מסיבית, נפרדת.$b$, $b$1) לפחד שאם אשתף פנטזיה, בן/בת הזוג יחשוב שהיא 'מבטאת' אותי. 2) לחשוב שפנטזיה צריכה להיות ביצוע. 3) לדחות פנטזיה של בן/בת הזוג כ'מוזרה'. 4) לשתף בכלל — ולפרש את כל הפנטזיות כדרישות.$b$, $b$פנטזיה היא כמו תא יומן פנימי. כשאני מראה לך עמוד אחד, אני מאמין/ה לך. אם תקרא/י בלי לשפוט — נפתח עוד עמוד.$b$,
  $b$השבוע: שיתפת/ה פעם אחת פנטזיה — ולא הזרת אותה למעשה?$b$, $b$שתפו השבוע פנטזיה אחת זה עם זה — בלי הצעה לבצע.$b$, $b$אל תפרש/י פנטזיה כדרישה. אל תשפט/י פנטזיה של בן/בת הזוג.$b$, $b$אתם מסוגלים לדבר על פנטזיות בלי לחץ. הן הפכו לחלק מהשיח.$b$
)
