-- Row #21: שלב 1 · אהבה וחיבור רגשי · סוגי התקשרות — איך אני אוהב/ת באמת
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-021',
  $b$סוגי התקשרות — איך אני אוהב/ת באמת$b$,
  $b$סו ג'ונסון לקחה את תיאוריית ההתקשרות של ג'ון בולבי — שפותחה במקור על ילדים — והוכיחה שהיא תקפה גם לזוגיות מבוגרת. אנחנו זקוקים לבן/בת הזוג שלנו ב'מסד נפשי' דומה לאיך שילד זקוק להורה: לדעת שהוא/היא 'שם בשבילי, כשאני זקוק/ה'.

שלושה סגנונות עיקריים: סגנון בטוח — אדם שגדל עם הורות זמינה, יודע לבקש בלי להתחנן ולקבל בלי להיתקע. סגנון חרד — אדם שלא היה בטוח אם ההורה יענה, ולכן 'מתעצם' כדי לוודא שלא יישכח. בריב הוא לוחץ, מבקש יותר, מתאמץ. סגנון נמנע — אדם שגדל בתחושה שהדרישה שלו לא תיענה ממילא, ולכן לומד 'אני לבד'. בריב הוא נסגר, נעלם, ממזער את הצורך.

האירוניה של זוגיות: רוב האנשים מתחתנים עם הסגנון המשלים. חרד מוצא נמנע, נמנע מוצא חרד. למה? כי כל אחד מוצא בשני את מה שמוכר לו מהילדות. ואז הם מנהלים את 'הריקוד': החרד רודף, הנמנע מתרחק. החרד מתעצב, הנמנע מתבצר. שניהם מתסכלים זה את זה — ושניהם מוצאים אחד בשני את האימות לפחד שלהם. החרד מקבל אישור: 'אכן, את/ה לא שם בשבילי'. הנמנע מקבל אישור: 'אכן, את/ה דורש/ת ממני יותר ממה שאני יכול/ה לתת'.

הפתרון של ג'ונסון אינו 'לתקן' את הסגנון — אלא להבין אותו, ולמצוא את הצורך שמתחת. החרד צריך לדעת "אני כאן, את/ה לא לבד". הנמנע צריך לדעת "לא תכריח/י אותי, אני יכול/ה להגיע אלייך מבחירה". כששני אלה מובנים, הריקוד הופך לדיאלוג.

תרגיל מפתח של EFT: זיהוי 'דרישת ההתקשרות' מתחת לכעס. כשאני כועס/ת על בן/בת הזוג, מתחת לכעס יש צורך — להיראות, להיאהב, להיוודע. אם אני יודע/ת לבטא את הצורך ולא את הכעס, בן/בת הזוג מסוגל/ת להיענות. אם אני נשאר/ת בכעס, הוא/היא נסגר/ת.

להבין את סגנון ההתקשרות זה לא 'תיקון' — זה תרגום. אני מתרגם/ת את ההתנהגות של בן/בת הזוג מ'הוא/היא לא רוצה אותי' ל'הוא/היא רוצה ופוחד/ת'. ובתרגום הזה — נולדת חמלה.$b$,
  $b$כל אחד עונה על שאלון התקשרות קצר (יש בחינם ברשת — 'ECR-S'). שתפו תוצאות. דברו על דפוסי הילדות שעיצבו את הסגנון. שאלו: 'מתי בריב אני בא/ה ממקום של חרד? מתי ממקום של נמנע? איך אנחנו יכולים לתת מענה זה לזה?'$b$,
  10021, 0, true, 'both',
  1,
  $b$Sue Johnson, Hold Me Tight (EFT)$b$, $b$Sue Johnson, Hold Me Tight (EFT)$b$,
  $b$תיאוריית ההתקשרות (בולבי, מורחב על ידי ג'ונסון לזוגיות) מציגה שלושה סגנונות עיקריים: בטוח, חרד, נמנע. לכל אחד דפוס תגובה שונה למתח בזוגיות. הבנת הסגנון שלי ושל בן/בת הזוג היא מפתח לפיענוח ריבים.$b$, $b$1) לחשוב שכולם מגיבים כמוני. 2) לפרש סגנון נמנע כ'לא אכפת לו/ה' (לא נכון — אכפת מאוד). 3) לפרש סגנון חרד כ'דרמה' (זו זעקת התקשרות). 4) לרצות 'לתקן' את הסגנון של בן/בת הזוג במקום להבין אותו.$b$, $b$סגנונות התקשרות כמו תוכנת הפעלה — אתה לא בוחר אותה, אבל אפשר להבין אותה ולתת לה אפדייטים.$b$,
  $b$השבוע: תפסת/ה את עצמך מגיב/ה במצב מתח בדפוס מוכר?$b$, $b$זהה/י סגנון בריב אחד השבוע. שאל/י את עצמך: 'איזה צורך התקשרותי לא נענה כאן?'$b$, $b$אל תפרש/י סגנון נמנע כקור. אל תפרש/י סגנון חרד כדרמטיות.$b$, $b$אתם מבחינים בריבים שלכם בדפוס — ויודעים לקרוא לו בשמו במקום לחזור אליו.$b$
)
