-- Row #22: שלב 1 · אהבה וחיבור רגשי · פגיעות — השער הצר אבל היחיד לאהבה
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-022',
  $b$פגיעות — השער הצר אבל היחיד לאהבה$b$,
  $b$ברנה בראון, חוקרת חברתית מאוניברסיטת יוסטון, השתפרה במונח 'פגיעות' לאחר שני עשורי מחקר על בושה. הממצא המרכזי שלה: פגיעות היא לא חולשה — היא הולדת האומץ. כל מה שאנחנו רוצים בחיים — אהבה, חיבור, יצירתיות, שייכות — דורש פגיעות.

בזוגיות, פגיעות מתבטאת בכל פעם שאני מסתכן/ת בלהיראות. אני אומר/ת 'אני אוהב/ת אותך' ראשון/ה. אני מודה ש'פחדתי שתעזוב/י'. אני מבקש/ת 'אני זקוק/ה לך עכשיו'. אני בוכה לפני בן/בת הזוג. אני מודה שטעיתי. כל אחד מאלה הוא רגע של חשיפה — וברגע הזה, או שמתקרבים או שמתרחקים.

הפחד שלנו מפגיעות הוא טבעי. אם אחשוף את עצמי, אני עלול/ה להיפצע. ואכן — לפעמים זה קורה. לכן רובנו לומדים, מילדות, להיות 'חזקים'. נוסיף שריון. ניצור מחיצה. ונרגיש בטוחים — אבל גם לבד.

בראון מציעה הבחנה חשובה: פגיעות אינה חשיפה ללא גבולות. היא חשיפה לאדם שראוי לה. בן/בת הזוג בזוגיות בריאה הוא/היא 'אדם בטוח'. שיתוף פגיעות איתו/ה נכון. עם אדם שלא בטוח — מסוכן. הבחירה החכמה היא לדעת מתי להיפתח, ולמי.

בזוגיות שהבסיס שלה בטוח, פגיעות הופכת למטבע יומיומי. "היה לי יום קשה — אני זקוקה לחיבוק". "אני מתבייש שבכיתי בעבודה". "חשבתי עליך כל היום ופחדתי שאתה כועס". כל אחד מאלה נראה קטן — אבל הם משדרים: 'אני סומך/ת עלייך עם הצדדים הרכים שלי'.

התרגול הזוגי הוא להעז ראשון/ה. רוב הזוגות מחכים שהשני יהיה פגיע ראשון. אבל הפגיעות היא הזמנה — מי שמתחיל, מאפשר לאחר. בלי שהמישהו יתחיל, שניהם נשארים מאחורי הקיר. זוגיות בריאה היא זוגיות בה שני הצדדים מתחילים, בקצב מתחלף, ושניהם יודעים שהפגיעות תיפגש בחמלה.

בראון אומרת: "איפה שיש פגיעות, יש אהבה. איפה שאין פגיעות, יש רק עסקה". ההבחנה הזו היא הכל.$b$,
  $b$כל אחד אומר השבוע משפט פגיע אחד שלא העז עד היום: 'אני מפחד/ת מ___', 'אני זקוק/ה ממך ל___', 'אני מתבייש/ת ב___'. בלי הסבר, בלי הצדקה. רק לומר. השני מקשיב, נושם, ואומר משפט אחד: 'אני שומע/ת אותך'.$b$,
  10022, 0, true, 'both',
  1,
  $b$Brené Brown, Daring Greatly$b$, $b$Brené Brown, Daring Greatly$b$,
  $b$ברנה בראון, חוקרת בושה ופגיעות, גילתה שלא ניתן לחיות את האהבה בלי להעז להיות פגיע. פגיעות אינה חולשה — היא שער. רוב הזוגות מתבצרים מאחורי שיריון, ושוקעים זה לצד זה, בלי לגעת באמת.$b$, $b$1) לחשוב שלהיות 'חזק/ה' זה לא להראות רגש. 2) לבחור באירוניה במקום בחשיפה. 3) לפחד שאם אגיד 'אני אוהב/ת אותך' ראשון/ה, אני 'מפסיד/ה'. 4) לחכות שהשני יהיה פגיע — בעוד אני מחכה.$b$, $b$פגיעות כמו דלת. סגורה — היא מגנה. אבל פתוחה — היא מאפשרת אהבה להיכנס.$b$,
  $b$השבוע: כמה פעמים בחרת בכוחנות במקום בפגיעות?$b$, $b$אמור/אמרי השבוע משפט אחד פגיע — בלי הסבר. תן/י לבן/בת הזוג להגיב.$b$, $b$אל תכסה/י פגיעות בהומור או בציניות. תן/י לה להישאר.$b$, $b$את/ה מצליח/ה להיות פגיע/ה — והקשר אחר כך מרגיש קרוב יותר.$b$
)
