-- Row #23: שלב 1 · אהבה וחיבור רגשי · רגשות רכים מתחת לרגשות קשים
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-023',
  $b$רגשות רכים מתחת לרגשות קשים$b$,
  $b$אחד הגילויים החזקים של EFT (הטיפול הזוגי הממוקד-רגש של סו ג'ונסון) הוא שזוגות נתקעים בריבים כי הם מנהלים אותם ברובד הלא נכון. הם מדברים מתוך 'הרגשות המשניים' — כעס, ביקורת, מגננה, אדישות — בעוד הרגשות שמניעים אותם הם 'הרגשות הראשוניים' — פחד, פגיעות, צורך, בושה.

ההבדל קריטי. כשאני אומר/ת "את/ה אנוכי/ת" — זה כעס. הצד השני שומע התקפה ומגיב במגננה. הריב מתסלם. אבל אם אני אומר/ת "כשאת/ה לא מתקשר/ת לפני שאת/ה מאחר/ת, אני מתחיל/ה לפחד שאת/ה לא חושב/ת עליי" — זה רגש ראשוני. הצד השני שומע פצע — ובדרך כלל מגיב בחמלה.

הקושי הוא שלהגיע לרגש הראשוני דורש פגיעות. הכעס הוא 'בטוח' — הוא נשק. הפחד הוא חשוף. ולכן רובנו, אינסטינקטיבית, נשארים בכעס. אנחנו צודקים, אנחנו מנצחים — ואנחנו לא נפתרים.

ג'ונסון מציעה תרגיל פנימי: לפני כל תגובה לבן/בת הזוג, לעצור 5 שניות ולשאול: 'מה הרגש מתחת לזה?'. בדרך כלל יש שלוש תשובות: (1) פחד — של אובדן, של נטישה, של לא להיות מספיק. (2) צורך — להיראות, להיאהב, להיות מובן/ת. (3) בושה — שאני לא ראוי/ה, שאני מאכזב/ת. ברוב הריבים, אחד משלושה אלה הוא המקור.

כשאני מזהה את הרגש הראשוני ומדבר/ת ממנו — קורה משהו פיזיולוגי בבן/בת הזוג. המוח שלו/ה מקבל הזמנה לחמלה, לא להגנה. החזה נפתח, העיניים מתרככות. במקום להתבצר, הוא/היא בא/ה לקראת. וזו תפנית בכל ריב.

התרגול הוא לא קל. דורש שנות תרגול לעבור מ'התקפה כעוסה' ל'הצהרת פגיעות'. אבל זוגות שלמדו את זה מספרים שהריבים שלהם השתנו לא רק בכמות (פחות) אלא בעוצמה (פחות הרסניים) ובאופן (פחות מתסלמים).

ג'ונסון מסכמת: "מאחורי כל כעס, יש פגיעות. מאחורי כל ביקורת, יש פצע. מאחורי כל הקפאה, יש פחד. אם אתה רוצה לאהוב — דבר/י מאיפה שאת/ה באמת".$b$,
  $b$ריב הקרוב — לפני שאת/ה משיב/ה, עצור/י: 'איזה רגש רך יש לי מתחת לכעס הזה? פחד? פגיעות? צורך?' ונסה/י לדבר משם. למשל, במקום "את/ה תמיד מאחר/ת" — "כשאת/ה מאחר/ת, אני מרגיש/ה לבד".$b$,
  10023, 0, true, 'both',
  1,
  $b$Sue Johnson, EFT — Primary vs Secondary Emotions$b$, $b$Sue Johnson, EFT — Primary vs Secondary Emotions$b$,
  $b$ב-EFT מבחינים: רגשות משניים (כעס, ביקורת, אדישות) הם השריון. רגשות ראשוניים (פחד, פגיעות, צורך, בושה) הם מתחת. רוב הריבים מתנהלים ברובד המשני — ולכן לא נפתרים. הקסם קורה כשמדברים מהראשוני.$b$, $b$1) להישאר בכעס כי 'מגיע לי'. 2) לחשוב שביקורת היא 'אמת מצמיחה'. 3) להאמין שאם אביע פחד, אני 'אאבד כוח'. 4) לראות בן/בת הזוג כועס/ת ולא לחפש מה מתחת.$b$, $b$רגש משני כמו אש. רגש ראשוני כמו עץ שמוקד. אם תכבה רק את האש — היא תחזור. צריך לטפל בעץ.$b$,
  $b$השבוע: כמה פעמים זיהית/ה רגש רך מתחת לכעס שלך — לפני שדיברת/?$b$, $b$בכל ריב השבוע — שאל/י את עצמך 'איזה פחד/צורך/בושה אצלי כאן?' לפני שאת/ה מגיב/ה.$b$, $b$אל תחזיק/י בכעס רק כי 'מגיע לך'. הוא חוסם פתרון.$b$, $b$אתם מצליחים לעבור מהתקפה לחשיפה — והוויכוחים מסתיימים בחיבוק במקום בקיר.$b$
)
