-- Row #24: שלב 1 · אהבה וחיבור רגשי · יחס 5:1 — המפתח להוקרה זוגית
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-024',
  $b$יחס 5:1 — המפתח להוקרה זוגית$b$,
  $b$ג'ון גוטמן הציע מסגרת פשוטה אבל חזקה: זוגיות היא חשבון רגשי. כל אינטראקציה היא תנועה — או הפקדה (חיוב) או משיכה (שלילי). זוגיות בריאה היא חשבון בעודף. וכמה עודף? לפחות 5 הפקדות לכל משיכה.

הממצא הזה התקבל אחרי מעקב של 30 שנה אחרי זוגות. גוטמן יכול היה לחזות בדיוק של 94% מי יישאר נשוי בעוד 10 שנים, רק על סמך היחס הזה. ב-5:1, הזוגיות בריאה. ב-3:1, היא בסכנה. ב-1:1 (כמות שווה של חיובי לשלילי), הגירושין הם בלתי נמנעים.

מה זו 'הפקדה'? לא רק 'אני אוהב אותך' או 'את יפה'. הפקדות יומיומיות הן: 'תודה שעשית את הקפה', מבט עם חיוך כשנכנסים הביתה, יד על הכתף בעוברים זה לצד זה, צחוק על בדיחה משותפת, הקשבה אמיתית כשבן/בת הזוג מספר/ת על היום, ציטוט של משהו ש'הוא/היא היה אומר/ת' (סימן שאתה זוכר את האחר). כל אחד מאלה הוא הפקדה.

הסיבה ל-5:1 ולא 1:1 היא נוירולוגית. המוח האנושי מתעדף שלילי על חיובי — מה שמכונה 'הטיית השליליות'. אינטראקציה שלילית אחת זוכרת חזק יותר מ-5 חיוביות. לכן צריך מאזן 5:1 רק כדי 'לא להיות מינוס'. כל הפקדה נוספת — היא רומנטיקה ממש.

התרגול היומיומי הוא להפוך הוקרה להרגל. בשעת הפנאי, אם אני שם/ה לב לקטן 'הצדק שלך', או 'אני מעריך/ה את הסבלנות שלך' — זו הפקדה. במהלך הריב, אם אני יודע/ת לעצור ולהגיד 'אני יודע/ת שאת/ה מתאמץ/ת' — זו הפקדה אפילו יותר חזקה (כי היא קשה יותר לתת).

התובנה החשובה ביותר ב-5:1 היא שזוגיות לא מתמוטטת ברגעים גדולים — היא נשחקת באלפי רגעי חוסר הוקרה. ובאופן הפוך — היא נבנית באלפי רגעי הוקרה זעירים. מי שמבין את זה ומתרגל מודע 30 הפקדות ביום — הזוגיות שלו/ה משתנה תוך חודש.$b$,
  $b$במשך שבוע, כל אחד מקיים 'הפקדות' מודעות: 5 הפקדות ביום. הפקדה היא: תודה ספציפית, מילה חיובית, חיבוק ספונטני, מבט מאשר, מסרון מתוק. בערב, סכמו: כמה הפקדות הצלחתי לעשות היום?$b$,
  10024, 0, true, 'both',
  1,
  $b$John Gottman, The Magic Ratio$b$, $b$John Gottman, The Magic Ratio$b$,
  $b$גוטמן מצא שזוגות מצליחים מקיימים יחס של 5:1 — חמש אינטראקציות חיוביות לכל אחת שלילית. זה לא רגעי דרמה — אלה רגעים זעירים: 'תודה', מבט, חיבוק, צחוק. היחס הזה מנבא 94% מהצלחת הזוגיות.$b$, $b$1) לחשוב שהזוגיות 'בריאה' אם אין ריבים — היחס יכול להיות 0:0 וזה גם בעיה. 2) להמתין לרגעים גדולים. 3) לחשוב שאם אמרתי 'אני אוהב/ת אותך' פעם, זה מספיק לחודש. 4) לפסול הוקרה קטנה כ'לא רומנטית מספיק'.$b$, $b$יחס 5:1 כמו חשבון בנק רגשי. כל הוקרה היא הפקדה. כל ריב הוא משיכה. מי שלא מפקיד מספיק — ייכנס לאוברדרפט.$b$,
  $b$השבוע: כמה הפקדות לעומת משיכות? אתם מעל 5:1?$b$, $b$5 הפקדות מודעות ביום. שמור/שמרי רישום השבוע.$b$, $b$אל תניח/י שב/בת הזוג 'יודע/ת' שאת/ה אוהב/ת. אמירה > הנחה.$b$, $b$אתם תופסים את עצמכם מבטאים הוקרה ספונטנית — בלי שצריך תרגיל.$b$
)
