-- Row #26: שלב 1 · אהבה וחיבור רגשי · אהבה כפועל — לא רק כרגש
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-026',
  $b$אהבה כפועל — לא רק כרגש$b$,
  $b$אריך פרום, פילוסוף ופסיכואנליטיקאי, פרסם ב-1956 את 'אומנות האהבה' — ספר שמשנה את הגישה לאהבה. הטענה המרכזית: אהבה אינה מצב שאנחנו 'נופלים' אליו. היא אומנות שלומדים אותה — כמו כל אומנות אחרת, דורשת ידע, תרגול וחיבור רוחני.

הבעיה ברוב הזוגות היא שהם לומדים על 'הימצאות באהבה' — אבל לא על 'איך לאהוב'. נקלעים לזוגיות בגיל 25 בלי שום הכשרה. כשהאהבה הראשונית דועכת, אין כלים. נקלעים לפחד שזה 'נגמר'. ובאמת — המצב הרגשי הראשוני אכן נגמר. אבל זה היה רק התחלה — לא האהבה עצמה.

פרום מציג ארבעה אלמנטים של אהבה כאומנות: (1) דאגה (Care) — אכפת לי מהשני באמת. (2) אחריות (Responsibility) — אני נענה/ת לצרכים שלו/ה. (3) כבוד (Respect) — אני רואה אותו/ה כמי שהוא/היא, לא כפי שאני רוצה. (4) הכרה (Knowledge) — אני מתעמק/ת בעולם שלו/ה.

צ'פמן (5 שפות אהבה) מתרגם את ההפשטה הזו לפעולות יומיות. אהבה היא לעשות, לא רק להרגיש. וההבחנה הזו היא מהפך. כי אם אהבה היא תחושה, אני לא יכול/ה לעשות איתה הרבה כשהיא דועכת — רק 'לקוות שתחזור'. אבל אם אהבה היא פעולה, אני יכול/ה לבחור לעשות אותה — וגם כשהתחושה לא שם, הפעולה מחדשת את התחושה.

המחקר תומך בזה. כשאני נוהג/ת כמי שאוהב/ת — מקפיד/ה על הוקרה, מגע, נוכחות, התעניינות — המוח שלי מתחיל לייצר את ההורמונים של אהבה. הפעולה מקדימה את התחושה. וכך, גם בתקופות שהזוגיות 'לא נדלקת' מאליה, אני יכול/ה להחזיר אותה — לא בלחיצה, אלא בתרגול עקבי.

שינוי תפיסה זו דורש בגרות. הצעיר רוצה אהבה ספונטנית. הבוגר/ה יודע/ת שאהבה ארוכת טווח דורשת התמדה. וההתמדה לא הופכת את האהבה לפחות אמיתית — היא הופכת אותה ליותר עמוקה. כי האהבה שמחזיקה בלי שאני 'מרגיש/ה אותה' כל שנייה — היא אהבה שאוהבת באמת.

פרום מסכם: "לאהוב מישהו אינו רק רגש חזק. זו החלטה, זו שיפוט, זו הבטחה".$b$,
  $b$כל אחד עורך רשימה של 5 פעולות אהבה שיעשה השבוע — ספציפיות, יומיות. למשל: 'אכין לו/ה את הקפה בבוקר', 'אגיד תודה ספציפית פעם בערב', 'אגלה דבר חדש על העולם הפנימי שלו/ה השבוע'. בסוף השבוע — סקירה זוגית.$b$,
  10026, 0, true, 'both',
  1,
  $b$Gary Chapman + Erich Fromm, The Art of Loving$b$, $b$Gary Chapman + Erich Fromm, The Art of Loving$b$,
  $b$פרום (1956): 'רוב האנשים חושבים שהבעיה באהבה היא למצוא את האדם הנכון. הבעיה האמיתית היא ללמוד איך לאהוב'. אהבה היא מיומנות — לא תחושה. צ'פמן מתרגם: זה שורה של פעולות יומיות, לא רק תחושה רגשית.$b$, $b$1) לחכות שהאהבה 'תחזור מאליה' אחרי שירדה. 2) להגדיר אהבה רק לפי תחושה. 3) לחשוב ש'אם אני אוהב/ת', אני יודע/ת איך לבטא. 4) לוותר על תרגול אהבה כי 'זה אמור להיות טבעי'.$b$, $b$אהבה כמו ספורט. גם השחקן הכי מוכשר חייב להתאמן יום-יום. בלי אימון — היכולת נעלמת.$b$,
  $b$השבוע: כמה פעולות אהבה ביצעת מודע — לא 'מאליו'?$b$, $b$5 פעולות אהבה ספציפיות השבוע. רשום/י אותן מראש — והוצא/י לפועל.$b$, $b$אל תחכה/י לתחושה. הפעולה מולידה את התחושה.$b$, $b$אתם רואים את האהבה כמשהו שאתם 'עושים' — לא רק 'מרגישים'.$b$
)
