-- Row #28: שלב 1 · אהבה וחיבור רגשי · ההיסטוריה הרגשית — מה אני מביא/ה איתי
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-028',
  $b$ההיסטוריה הרגשית — מה אני מביא/ה איתי$b$,
  $b$אחת התובנות החשובות בטיפול זוגי היא שאין שני אנשים בזוגיות — יש שש. שני בני הזוג עצמם, ובכל אחד מהם — אבא, אמא, וההיסטוריה הקצרה הראשונה שלמדו על אהבה. כל ריב, כל קונפליקט, כל רגע של עצבים — מצטטים גם את ההיסטוריה הזו.

התופעה הזו נקראת 'העברה' (Transference). אני מגיב/ה לבן/בת הזוג שלי — אבל בעוצמה שאינה תואמת לרגע. למה? כי הרגע הנוכחי 'מצטט' רגע מהילדות. אם אבא היה מבטל את הרגשות שלי, וכעת בן/בת הזוג שכח/ה לשאול איך עבר היום — אני מגיב/ה כאילו הוא/היא אבא. הכאב האמיתי הוא לא של הרגע — הוא של 30 שנה.

ג'ון ובלינדה גוטמן מציגים את 'תרגיל ההיסטוריה הרגשית' — שיחה מובנית בה כל אחד מספר על דמויות מפתח בילדותו. איזה צד של אבא הוטמע בי? איך אמא הביעה אהבה — או לא? מי היה בן הזוג הראשון, ומה הוא לימד אותי על מה זה 'להיות איתי'? כל תשובה היא חתיכה במפה.

הקסם של השיחה הזו הוא שני: ראשית, אני מבין/ה למה אני מגיב/ה איך שאני מגיב/ה. אם אמא ביטלה אותי — אני רגיש/ה במיוחד כשבן/בת הזוג מבטל/ת. שנית, בן/בת הזוג מבין/ה אותי באופן עמוק יותר. כשהוא/היא יודע/ת על אמא, התגובה שלי הופכת ממוזרה לסבירה. הוא/היא יכול/ה להגיב בחמלה במקום בהגנה.

אבל יש סיכון: אסור להפוך את ההיסטוריה לתירוץ. "זה בגלל אבא שלי" — לא פותר. ההיסטוריה היא הסבר, לא היתר. האחריות עליי לזהות את הדפוס ולעבוד עליו. החמלה של בן/בת הזוג היא תמיכה — לא מינוי שלו/ה כמטפל/ת שלי.

ג'ונסון מוסיפה רובד: כשאני יודע/ת על ההיסטוריה של בן/בת הזוג, אני יכול/ה לתת לו/ה במודע מה שהוא/היא לא קיבל/ה. אם הוא נדחה הרבה ילדות — אני יכול/ה להיות בטוח/ה לו, להישאר נוכח/ת, להגיב בעקביות. הזוגיות הופכת ל'תיקון' — לא של ההורות (אסור), אלא של היכולת לבטוח.

הזוגיות היא, במובן עמוק, הזדמנות שנייה. לא לחזור על מה שהיה — אלא לחיות סוף אחר. ובשביל זה, צריך להכיר את ההיסטוריה — של עצמי, ושל האחר.$b$,
  $b$כל אחד עורך 'מפת היסטוריה רגשית' — שלוש דמויות מההיסטוריה שלי שעיצבו אותי. מה למדתי על אהבה מאמא? מאבא? ממערכת יחסים אחת קשה? איך זה מתבטא בזוגיות שלנו? שתפו זה את זה — מתוך סקרנות, לא טינה.$b$,
  10028, 0, true, 'both',
  1,
  $b$Family of Origin Theory + Sue Johnson$b$, $b$Family of Origin Theory + Sue Johnson$b$,
  $b$כל אחד מאיתנו מביא לזוגיות לא רק את עצמו, אלא גם את ההורים שלו, האחים, החברויות, ההיסטוריה. רוב הקונפליקטים בזוגיות נדלקים על דפוסים מההיסטוריה — ולא על המצב הנוכחי.$b$, $b$1) לחשוב שאני 'נכנס/ת לזוגיות נקי/ה'. 2) להגיב לבן/בת הזוג כאילו הוא/היא ההורה שלי. 3) לא להבין למה דבר קטן 'מפעיל' אותי בלי פרופורציה. 4) להאשים את בן/בת הזוג בכאב היסטורי שלי.$b$, $b$הזוגיות כמו תיאטרון — שני שחקנים על הבמה, אבל יש קלעים מאחור. הקלעים שלי מאוכלסים בכל הדמויות מהילדות שלי. וגם של בן/בת הזוג.$b$,
  $b$השבוע: זיהית/ה רגע שבו הגיב/ה בך 'הילד/ה' ולא 'המבוגר/ת'?$b$, $b$שיחה אחת השבוע על 'דמות אחת מהילדות שעיצבה את האהבה שלי'.$b$, $b$אל תהפוך/י היסטוריה לתירוץ. היא הסבר — לא פטור.$b$, $b$אתם מבינים תגובות לא-פרופורציוניות בזוגיות — ויודעים לקרוא להן בשמן.$b$
)
