-- Row #29: שלב 1 · אהבה וחיבור רגשי · הריקוד של רודף-מתרחק — לפענח את הקסם הקטלני
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-029',
  $b$הריקוד של רודף-מתרחק — לפענח את הקסם הקטלני$b$,
  $b$סו ג'ונסון, ב-EFT, זיהתה דפוס מסוים שחוזר ברוב הזוגות במצוקה. היא קוראת לו 'דיאלוג שטני' — וזה דיאלוג מסוג 'רודף-מתרחק'. צד אחד דורש קרבה (שואל, מבקר, לוחץ). צד שני בורח לחופש (נסגר, יוצא, מתעלם). שניהם מנסים להתחבר — אבל הריקוד עצמו מפריד.

הצד הרודף בדרך כלל יחזיק 'אני זה שאכפת לו'. הצד המתרחק יחזיק 'אני זה שמכבד מרחב'. שני הצדדים בטוחים שהבעיה אצל האחר. "אם רק היה מתעניין יותר". "אם רק הייתה מפסיקה ללחוץ". אבל ג'ונסון מראה שזה הריקוד עצמו — לא אחד מהצדדים — שהוא הבעיה.

כדי לשבור את הריקוד, צריך לזהות אותו ברגע שהוא מתחיל. הסימנים: היא מציעה משהו, הוא לא עונה. היא חוזרת ביתר חוזק. הוא נסגר עוד יותר. הקצב הזה הוא הריקוד. ברגע שהוא מתחיל — אני יכול/ה להבין: 'אנחנו בריקוד עכשיו'. וזה רגע ההזדמנות.

מתחת לריקוד יש שני צרכים אמיתיים. הרודף זקוק לאישור: 'אני חשוב/ה לך, את/ה לא הולך/ת'. המתרחק זקוק לכבוד: 'אני אהוב גם בלי הלחץ הזה'. כששני הצרכים גלויים, הריקוד נעצר. הרודף לא צריך לרדוף יותר. המתרחק לא צריך לברוח.

התרגיל של ג'ונסון הוא 'מילת קוד'. שני בני הזוג מסכימים על מילה אחת ('עצור', 'טנגו', 'ריקוד') שכל אחד יכול להוציא באמצע ריב כדי לסמן: 'אנחנו ברצף שוב'. ברגע שהמילה יוצאת, שניהם עוצרים. לא ממשיכים. שמים ידיים על הלב. נושמים. ואומרים: "אני רואה שאני רודף/ת. הצורך שלי הוא X". "אני רואה שאני מתרחק/ת. הצורך שלי הוא Y".

הקסם בכל זה הוא שאחרי שזה קורה כמה פעמים, הריקוד מאבד מכוחו. אנחנו לא נופלים אליו אוטומטית. אנחנו רואים אותו לפני שאנחנו בו, ויודעים מה לעשות. הזוגיות יוצאת מ'מלכודת חוזרת' לדינמיקה חיה.

ג'ונסון אומרת: "הבעיה היא לא שני בני הזוג. הבעיה היא הריקוד. ושני בני הזוג יכולים, ביחד, לבחור ריקוד אחר".$b$,
  $b$שיחה זוגית על: 'איזה צד של הריקוד אני? באילו רגעים?'. כל אחד מזהה את עצמו. הסכימו על 'מילת קוד' — מילה אחת ('טנגו!', 'ריקוד', 'עצור') שמישהו יכול להוציא באמצע ריב לציין: 'אנחנו בדפוס שוב'. ברגע שהיא יוצאת — שניכם עוצרים, נושמים, ועוברים לדבר על הצרכים מתחת.$b$,
  10029, 0, true, 'both',
  1,
  $b$Sue Johnson, Hold Me Tight — Demon Dialogues$b$, $b$Sue Johnson, Hold Me Tight — Demon Dialogues$b$,
  $b$ג'ונסון מזהה דפוס ריב חוזר: צד אחד 'רודף' (פניות, ביקורת, לחץ), השני 'מתרחק' (סגירה, השתקה, יציאה). שניהם מנסים להתחבר — אבל הריקוד עצמו הוא הסיבה לניתוק.$b$, $b$1) לחשוב שהבעיה היא רק 'אצל השני'. 2) להתעצם ברדיפה כשהאחר מתרחק. 3) להתבצר במניעות כשהאחר רודף. 4) לא להבחין בריקוד כדפוס — ולהאשים מצב או נושא ספציפי.$b$, $b$כמו ריקוד טנגו עיוור. כל צעד שלי מאלץ צעד שלך. כשתופסים את התבנית — אפשר להחליף ריקוד.$b$,
  $b$השבוע: זיהיתם רגע של 'ריקוד' — והצלחתם לעצור אותו?$b$, $b$הסכימו על מילת קוד. הוציאו אותה פעם אחת השבוע — גם אם רק לתרגול.$b$, $b$אל תתעקש/י על להמשיך לדבר כשהריקוד פעיל. עצירה ראשית — דיבור אחר כך.$b$, $b$אתם מבחינים בריקוד ועוצרים אותו — לפני שהוא מסלים.$b$
)
