-- Row #30: שלב 1 · אהבה וחיבור רגשי · הצורך הנסתר — מה אתה באמת רוצה
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'emotional_connection' LIMIT 1),
  'csv-s1-emotional_connection-030',
  $b$הצורך הנסתר — מה אתה באמת רוצה$b$,
  $b$ג'ונסון, ב-Hold Me Tight, מציגה רעיון מרכזי: כל בקשה זוגית היא רק 'פנים' של משהו עמוק יותר — צורך התקשרות. שלושה צרכים בסיסיים שלפיהם המוח שלנו מבקש בכל רגע: "אתה זמין?", "אתה רואה אותי?", "אתה איתי?".

כשבקשה לא נענית, הצורך מתחת מורגש. אבל כשהבקשה נענית בלי שהצורך מורגש, הריגוש לא נחווה. דוגמה: אישה מבקשת מבעלה לחזור מוקדם מהעבודה. הוא חוזר. אבל היא לא מרגישה טוב. למה? כי הצורך מתחת לא היה 'שיחזור מוקדם' — הוא היה 'שירצה לחזור מוקדם'. הוא ענה לבקשה, אבל לא לצורך.

הסיבה שזה קורה היא שאנחנו לא תמיד יודעים — או מעיזים — לבטא את הצורך עצמו. "אני זקוקה לדעת שאתה רוצה אותי" זה משפט מפחיד. הוא חושף יותר מדי. אז אנחנו מבטאים אותו דרך בקשות חיצוניות — "תחזור מוקדם", "תקנה לי פרחים", "תזכור את התאריך". אבל גם כשהבקשה ממומשת, הצורך לא נענה — כי הצד השני לא ידע שזה הצורך.

התרגול של ג'ונסון הוא לזהות את הצורך מתחת לבקשה — ולבטא אותו ישירות. במקום "אתה תמיד שוכח את התאריכים" — "אני זקוקה לדעת שאני חשובה לך מספיק לזכור". במקום "אנחנו לא מדברים" — "אני זקוק לדעת שאתה עוד מתעניין/ת בי". הניסוח השני יותר פגיע — אבל הוא יותר תקשורתי.

כשבן/בת הזוג שומע/ת את הצורך, הוא/היא יכול/ה להיענות לעומק — לא רק לפעולה. הפרחים מקבלים כיתוב. החזרה מהעבודה מתלווה במבט. הקפה בבוקר נעשה במחוות אהבה. הפעולה זהה — אבל הצורך נענה.

וכשהצורך נענה, יש שינוי בגוף. הגוף 'נושם'. מערכת העצבים נרגעת. אני מרגיש/ה 'בית'. וזו ההגדרה של אהבה זוגית בריאה לפי ג'ונסון: זוגיות שבה אני יודע/ת שהצרכים שלי לא רק מבוטאים — אלא נראים.

התרגול הוא קבוע. כל פעם שעולה בקשה חוזרת, שאל/י את עצמך: 'מה הצורך התקשרותי מתחת?'. ובטא/בטאי אותו במקום או בנוסף לבקשה. הזוגיות שלך תשתנה ברמה אחרת — לא בגלל שהדברים יעברו טוב יותר, אלא בגלל שתרגישו אחד את השני יותר עמוק.$b$,
  $b$כל אחד מזהה בקשה אחת חוזרת שלו לבן/בת הזוג. שואל את עצמו: 'מה הצורך התקשרותי מתחת? לדעת שהוא/היא איתי? לדעת שאני חשוב/ה? לדעת שלא אהיה לבד?'. ואז מבטא את הצורך הזה ישירות לבן/בת הזוג. בלי הבקשה. רק הצורך.$b$,
  10030, 0, true, 'both',
  1,
  $b$Sue Johnson, Hold Me Tight$b$, $b$Sue Johnson, Hold Me Tight$b$,
  $b$ג'ונסון: מתחת לכל בקשה זוגית, יש 'צורך התקשרות' — הבקשה לדעת 'אתה איתי, אתה רואה אותי, אתה לא ילך'. רוב הזוגות מתקשרים את הבקשה החיצונית, אבל לא את הצורך מתחת — וגם אם הבקשה ממומשת, הצורך נשאר ריק.$b$, $b$1) לפתור בקשה חיצונית בלי לראות מה מתחת. 2) להאשים את עצמך 'אני יותר מדי דורש/ת'. 3) לא לבטא את הצורך כי 'מה ייחשבו עליי'. 4) לחפש מענה לצורך התקשרותי במקומות לא נכונים (עבודה, ילדים, רשתות).$b$, $b$הבקשה היא הקצף. הצורך הוא הקפה מתחת. אם השני שותה את הקצף, הוא לא טעם הקפה.$b$,
  $b$השבוע: כמה פעמים זיהית/ה צורך התקשרותי מתחת לבקשה שלך?$b$, $b$זהה/י בקשה חוזרת שלך — והבטא/בטאי את הצורך התקשרותי מתחתיה.$b$, $b$אל תסתפק/י בבקשה חיצונית. הצורך מתחת הוא העיקר.$b$, $b$אתם מבטאים צרכים התקשרותיים בגלוי — והם מקבלים מענה.$b$
)
