-- Row #32: שלב 1 · חברות ושותפות יומיומית · העומס המנטלי — מי באמת מנהל את הבית
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'friendship' LIMIT 1),
  'csv-s1-friendship-032',
  $b$העומס המנטלי — מי באמת מנהל את הבית$b$,
  $b$אווה רודסקי, עורכת דין שהתחילה לחקור עבודת בית אחרי שתפסה את עצמה במשימה השלישית של היום עם רשימה של 25 פריטים, חוללה מהפכה. בספרה Fair Play היא מסבירה שאין דבר 'חלוקת עבודה צודקת' אם לא מחלקים גם את העבודה המנטלית.

עבודה גלויה: לעשות את הכלים, לקחת את הילדים מבית הספר, להוציא את הזבל. עבודה מנטלית: לזכור שהילדה צריכה תיק חדש, לקבוע את התור לרופא השיניים, לתכנן את התפריט השבועי, לקנות את המתנה לבר מצווה של בן הדודן. אלה לא 'משימות' — אלה אחריויות שמלוות אותי כל הזמן.

המחקר ברור: ב-75% מהזוגות ההטרוסקסואליים, האישה נושאת את רוב העומס המנטלי. גם בזוגות שבהם הגבר 'עוזר הרבה' בעבודה גלויה. כי הוא 'עוזר' לפי דרישה — היא מנהלת את כל הבית בראש שלה. זה התש שלא נראה — ושנשחק עליו לאט.

הפתרון של רודסקי הוא 'בעלות מלאה' (Full Ownership). לא 'עזרה' — בעלות. כשאני בעלים של 'הסעת ילדים לחוגים' — זה אומר שאני מי שיודע איזה חוג מתי, מי הקבוצה הזוכה את האח, מתי השנה זה מתחיל. כל ההחלטות, התכנון והביצוע. בן/בת הזוג לא 'מנהל/ת' אותי על המשימה.

התרגיל הוא לקחת רשימה של ~30 משימות בית, ולחלק אותן ל'בעלות'. כל אחד הוא בעלים מלא של ~15 משימות. בעלים מלא = יודע, מחליט, מבצע, ומקבל אחריות לתוצאות. אם בן/בת הזוג בעלים של 'אוכל בבית', אני לא שואל/ת מה אוכלים. אני סומך/ת. וכשמשהו לא נעשה — זה התסכול שלו/ה לפתור, לא שלי לקטר עליו.

המעבר הזה דורש אומץ משני הצדדים. הצד שמחזיק את העומס צריך לסמוך — לא להתערב, לא 'לבדוק'. הצד שמקבל אחריות צריך להוכיח אמינות — לא להתפחס. בהתחלה זה קשה. אחרי חודש, רוב הזוגות מספרים שהמתח החדר.

רודסקי מסכמת: 'יש שני סוגי שותפים — שותפים שעוזרים, ושותפים שמשתתפים. רק השני באמת מקל'. ההבדל הוא במנטלית, לא בגלויה.$b$,
  $b$ערכו 'מבדק עומס מנטלי'. כל אחד רושם את כל המשימות (גלויות + מנטליות) שהוא אחראי עליהן. השוו. תופתעו. בחרו 3 משימות מנטליות שאחת מכן/ם תעביר/יעביר במלואן (כולל ההחלטות) לצד השני לחודש.$b$,
  10032, 0, true, 'both',
  1,
  $b$Eve Rodsky, Fair Play$b$, $b$Eve Rodsky, Fair Play$b$,
  $b$רודסקי מבחינה: יש 'עבודה גלויה' (לעשות) ו'עבודה מנטלית' (לחשוב). רוב הזוגות מחלקים את הראשונה — אבל המנטלית נופלת על אחד הצדדים (בדרך כלל האישה). זה מקור לא ידוע לתסכול עמוק.$b$, $b$1) לחשוב שאם 'עזרתי בכלים', אני שותף בעומס. 2) לחכות שיגידו לי מה לעשות (זו כבר מנטלית). 3) להניח 'היא תאמר אם היא צריכה'. 4) לא להבחין שניהול הוא עבודה.$b$, $b$עבודה גלויה כמו לבשל ארוחה. עבודה מנטלית כמו לתכנן את כל התפריט השבועי, לקנות, לזכור אלרגיות. רק הראשונה נראית — שתיהן תובעות.$b$,
  $b$השבוע: כמה דברים החלטת בלי לשאול את בן/בת הזוג? כמה הוא/היא?$b$, $b$ערכו רשימת משימות מנטליות. חלקו 3 בעלות מלאה השבוע — ואל תתערבו בהן.$b$, $b$אל תשאל/י 'מה אני צריך/ה לעשות?'. שאל/י את עצמך 'איזו אחריות לקחתי?'.$b$, $b$שניכם מנהלים תחומים — לא רק מבצעים משימות. ויש פחות תסכול 'שכוח'.$b$
)
