-- Row #34: שלב 1 · חברות ושותפות יומיומית · אני, את/ה, ואנחנו — שלוש זהויות בזוגיות
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'friendship' LIMIT 1),
  'csv-s1-friendship-034',
  $b$אני, את/ה, ואנחנו — שלוש זהויות בזוגיות$b$,
  $b$הספר העברי של מיאושי פותח את 10 הדיברות שלו ב'אני בזוגיות'. הפרק הראשון, לפני סקס, לפני תקשורת, לפני אהבה — הוא ה'אני'. ולא במקרה. כי בלי 'אני' מובחן, אין למי להתחבר.

אסתר פרל מציגה מסגרת דומה: בזוגיות בריאה יש שלוש זהויות פעילות. (1) ה'אני' — אדם עצמאי עם תחומי עניין, חברים, מטרות, וזהות שלא תלויים בבן/בת הזוג. (2) ה'את/ה' — האדם השני, מוערך וגם מובחן. (3) ה'אנחנו' — הזוגיות עצמה, היחידה השלישית שהיא לא רק סכום של השניים.

הבעיה הנפוצה היא שאחרי שנים של זוגיות, ה'אני' נמחק. אנחנו לומדים לחשוב כ'אנחנו' בלבד. "מה אנחנו אוהבים?". "איפה אנחנו נוסעים?". וזה נשמע יפה — אבל זה גם מסוכן. כי אם ה'אני' לא קיים, אין למי להתאהב. אני אוהב/ת בן/בת זוג עם פנים, חלומות, סקרנות. אם הם נמחקו ב'אנחנו' — האהבה דועכת.

פרל מציעה הבחנה: גשר חזק בנוי משני עמודים נפרדים, שמתחברים. אם העמודים מתמזגים, הגשר נופל. בזוגיות בריאה, שני אנשים שלמים בוחרים להיות ביחד — לא חצויים. ובדיוק העובדה ששניהם שלמים היא מה שמאפשר את הבחירה. אנחנו לא 'משלימים זה את זה' — אנחנו מצטרפים זה לזה.

התרגול הוא לטפח את ה'אני'. (1) זמן לבד — שעות בשבוע שאני מבלה לבדי, בעיסוקים שלי. (2) חברויות נפרדות — אנשים שאני מכיר/ה ואת/ה לא. (3) מטרות אישיות — חלום שאני שואף/ת אליו, גם אם בן/בת הזוג לא חולק/ת. (4) פרטיות — מקום פנימי שלי, לא הכל גלוי לאחר. (5) צמיחה — אני ממשיך/ה ללמוד, להתפתח, להשתנות.

החשש הנפוץ הוא ש'אני' מתחזק יוחזר על חשבון 'אנחנו'. ההפך הוא הנכון. ככל שאני שלם/ה יותר, אני מביא/ה יותר לזוגיות. ככל שאני יודע/ת מי אני, אני בוחר/ת בך מתוך מקום אמיתי. הזוגיות הופכת ל'אני אוהב/ת אותך' — לא ל'אני זקוק/ה לך'. וזה הבדל קוסמי.

הזוגיות בריאה היא לא איחוד — היא חיבור. שני 'אני' שלמים שיוצרים 'אנחנו' חי. ולפעמים, צריך להזכיר ל'אני' שיש לו זכות לקיום.$b$,
  $b$כל אחד עורך רשימה: 'מה האני שלי? מה הצרכים שלי האישיים? מה אני עושה לעצמי, בלי בן/בת הזוג?'. שתפו זה את זה. הסכימו: כל אחד יקבל זמן 'אני' אישי השבוע — לפחות שעתיים בלי משא ומתן.$b$,
  10034, 0, true, 'both',
  1,
  $b$Esther Perel + הספר העברי$b$, $b$Esther Perel + הספר העברי$b$,
  $b$פרל: זוגיות בריאה דורשת שלוש זהויות — אני (האינדיבידואל), את/ה (האחר), אנחנו (הזוגיות). אם 'אנחנו' מבטל את 'אני', הזוגיות נחנקת. אם 'אני' מבטל את 'אנחנו', אין זוגיות.$b$, $b$1) להפסיק לפתח את 'אני' אחרי שהתחתנו. 2) לראות עצמאות של בן/בת הזוג כאיום על הזוגיות. 3) לעשות הכל ביחד — ולאבד את הריגוש מההפרדה. 4) להפך — לחיות חיי 'אני' מקבילים, בלי 'אנחנו' אמיתי.$b$, $b$כמו שלושה כלי נגינה. כל אחד עומד לבדו. ביחד, הם יוצרים סימפוניה — אבל רק אם כל אחד שומר על הצליל שלו.$b$,
  $b$השבוע: כמה זמן השקעת ב'אני' שלך — בנפרד מהזוגיות?$b$, $b$השבוע — שעתיים לפחות לבד, בעיסוק שאת/ה בוחר/ת. בלי הצדקות.$b$, $b$אל תזניח/י את ה'אני' שלך כי 'אין זמן'. הוא בסיס לזוגיות.$b$, $b$אתם מכבדים את העצמאות אחד של השני — וגם נהנים יותר מהיחד.$b$
)
