-- Row #35: שלב 1 · חברות ושותפות יומיומית · כסף בזוגיות — השיחה שכולם דוחים
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'friendship' LIMIT 1),
  'csv-s1-friendship-035',
  $b$כסף בזוגיות — השיחה שכולם דוחים$b$,
  $b$ברדלי קלונץ, פסיכולוג כספים, גילה משהו מטלטל: כל אחד מאיתנו נושא 'תסריט כסף' לא מודע — אמונות שלמדנו בילדות על מה כסף 'אומר' עלינו. ארבעה תסריטים עיקריים: (1) 'כסף הוא רע' — אנשים אמיתיים לא מתעניינים בו. (2) 'כסף הוא הכל' — מי שיש לו, הוא מי שמצליח. (3) 'יש מספיק' — אופטימיות, לפעמים יתר. (4) 'אין מספיק' — חרדת מחסור, גם בעודף.

התסריטים האלה מעצבים כל החלטה כספית. וכשבן/בת זוג מצטרף לזוגיות עם תסריט שונה, ויכוחי הכסף הם לא רק על הכסף — הם על הסיפורים. אחד אומר 'בוא נחסוך'. השני שומע 'את/ה לא מאמינ/ה בנו'. אחד אומר 'בוא נהנה'. השני שומע 'את/ה לא אחראי/ת'.

גוטמן ממליץ על 'דייט כסף' — שיחה מבוננה של שעה, פעם בחודש, רק על הכסף. לא על הוויכוח שהיה אתמול. לא על אישומים. שיחה על: מטרות, פחדים, משאלות. מה אנחנו רוצים בעוד 5 שנים? מה הפחד הגדול שלנו עכשיו? איך נחסוך, איך נבזבז, איך נשמור.

התרגיל הראשון בכל זוגיות הוא להכיר את הסיפורים. לא 'מה את/ה חושב/ת על כסף' — אלא 'מה למדת על כסף'. אבא היה דואג? אמא הסתירה הוצאות? כסף קישר לאהבה ("אם תהיה ילד טוב, אקנה לך")? כל סיפור הוא רובד שאני מביא לזוגיות.

אחרי שמכירים את הסיפורים, הוויכוחים משתנים. הם לא 'את/ה לא אחראי/ת' — אלא 'אני מבינה שהפחד שלך הוא ש___, ואני זקוקה ש___'. השיחה הופכת מקרב לדיאלוג.

הצעדים המעשיים: (1) שלוש קופות — 'אני', 'את/ה', 'אנחנו'. כל אחד מקבל קצבה אישית שאינה מצריכה דין וחשבון. (2) הוצאות מעל סכום מסוים — בהסכמה. (3) שיחה חודשית — דייט כסף קבוע. (4) מטרה משותפת — חיסכון לחופשה, לדירה, לקייטנה.

כסף הוא לא נושא שולי. הוא חלק מרכזי בזוגיות. וזוגות שמדברים עליו פתוח — בלי בושה, בלי שיפוט — מצליחים בו, ובכל מה שמחוצה לו.$b$,
  $b$כל אחד עונה: 'מה למדתי על כסף בילדות? מה אבא/אמא היו אומרים? מה הפחיד אותי? מה ריגש?'. שתפו זה את זה. אחר כך — צאו לדייט הכסף: שיחה של שעה על המטרות שלכם, הפחדים, ואיך אתם רוצים להתנהל ב-3 השנים הבאות.$b$,
  10035, 0, true, 'both',
  1,
  $b$John Gottman + Bradley Klontz, Money Scripts$b$, $b$John Gottman + Bradley Klontz, Money Scripts$b$,
  $b$גוטמן: כסף הוא אחת משלוש הסיבות הראשונות לוויכוחים זוגיים (יחד עם סקס וילדים). קלונץ: לכל אחד יש 'תסריט כסף' מילדות — שמכתיב גישה לא מודעת לכסף. בלי לדבר על הסיפור הזה, ויכוחי הכסף לא יסתיימו.$b$, $b$1) להניח שאם 'הכסף בסדר', אין על מה לדבר. 2) לשפוט את הגישה של בן/בת הזוג ('את/ה בזבזן/ית', 'את/ה קמצן/ית'). 3) לדבר על כסף רק כשיש חוב או משבר. 4) להפריד חשבונות לחלוטין — או לאחד הכל בלי שיחה.$b$, $b$כסף הוא לא רק מספר — הוא סיפור. הסיפור שלי, שלך, ושלנו. בלי להבין את הסיפורים, המספרים תמיד יריבו.$b$,
  $b$השבוע: כמה ויכוחי כסף הצלחתם להפוך לשיחות?$b$, $b$דייט כסף השבוע — שעה אחת, בלי שיפוט, רק שיחה.$b$, $b$אל תאשם/י את בן/בת הזוג בגישה כלכלית. נסה/י להבין מאיפה היא באה.$b$, $b$אתם מדברים על כסף בלי לחץ — ויש לכם תוכניות משותפות.$b$
)
