-- Row #38: שלב 1 · חברות ושותפות יומיומית · תחביבים נפרדים — האוויר של הזוגיות
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'friendship' LIMIT 1),
  'csv-s1-friendship-038',
  $b$תחביבים נפרדים — האוויר של הזוגיות$b$,
  $b$הספר העברי של מיאושי מציין שתחביבים נפרדים הם 'אוויר' של הזוגיות. אסתר פרל מסכימה: כדי לבעור את האחר, צריך להישאר אדם לעצמך. תחביב נפרד הוא לא בריחה מהזוגיות — הוא הון שאתה צובר ומביא אליה.

הבעיה אצל זוגות רבים אחרי 5 שנים היא שכל פעילות הופכת ל'משותפת'. אם רצתי לפני הזוגיות, עכשיו 'אנחנו רצים יחד' — או לא רצים בכלל. אם אהבתי לקרוא, עכשיו אני קוראת רק כשהוא ישן. אנחנו 'עושים הכל ביחד', וכל אחד הולך לאיבוד.

הסכנה היא תלות הדדית (codependence). אני לא יכול לעשות שום דבר לבד. וברגע שאני לא יכול/ה — אני מתחיל/ה לכעוס על בן/בת הזוג שהוא/היא 'תופס/ת' את כל החיים שלי. זה לא הוגן — אני זה שוויתר/ה. אבל זה התחושה.

התחביב הנפרד הוא תיקון. הוא אומר: 'אני אדם שלם, גם בלעדיך'. ופרדוקסלית, זה הופך אותי ליותר אטרקטיבי/ת. כי אדם עם עניינים משלו, חברים משלו, תשוקות משלו — הוא מסקרן. אדם שכל חייו 'אנחנו' — הוא משעמם. גם לעצמו.

פרל מציינת שזה אחד הסודות של תשוקה ארוכת טווח. כשאני רואה את בן/בת הזוג שלי 'בעולם שלו/ה' — מנגן/ת, מצייר/ת, רץ/ה — אני נמשך/ת מחדש. כי אני רואה את האדם שמתאהבתי בו/ה — לא את שותף/ת הלוגיסטיקה. הצד הזה הוא אטרקטיבי בדיוק כי הוא לא תלוי בי.

כיצד מטפחים תחביבים נפרדים בלי לפגוע ב'אנחנו'? כמה כללים: (1) זמן קבוע, מתוכנן. תחביב הוא לא 'אם יישאר זמן' — הוא בלוח. (2) הסכמה הדדית. אנחנו מסכימים שזה חשוב לשנינו. (3) חזרה עם סיפורים. בעלת/בעל החזרה מהתחביב מספר/ת מה היה — ובן/בת הזוג מסקרן/ת באמת. (4) פעם בחודש, לפחות, תחביב משותף — לא כל הזמן, לא אף פעם.

תחביב נפרד דורש בגרות. זה דורש ביטחון מבן/בת הזוג שאת/ה לא 'בורח/ת'. וזה דורש שאת/ה תוכיח/י שאת/ה לא בורח/ת. הזוגיות היא הבית. התחביב הוא הטיול. שניהם נחוצים — ושניהם משלימים.$b$,
  $b$כל אחד בוחר תחביב אחד אישי לעסוק בו לפחות שעתיים בשבוע. לא ביחד. לא לדווח. רק לעשות. אחרי 4 שבועות, שתפו מה זה נתן לכם — ולזוגיות.$b$,
  10038, 0, true, 'both',
  1,
  $b$הספר העברי + Esther Perel$b$, $b$הספר העברי + Esther Perel$b$,
  $b$הספר העברי של מיאושי ופרל מסכימים: עיסוק נפרד מטפח את הזוגיות. תחביב משלי הוא לא איום על האהבה — הוא חידוש המים שאני מביא/ה אליה. חיים משעמשים יוצרים זוגיות משעממת.$b$, $b$1) להפסיק לעשות תחביבים שאהבת לפני הזוגיות. 2) להשתתף בכל תחביב של בן/בת הזוג מתוך 'חובה'. 3) לראות זמן נפרד כסיבה לקנאה. 4) לוותר על תחביב כדי 'לעשות הכל ביחד'.$b$, $b$תחביב נפרד כמו אוויר נפרד שאתה נושם. אם רק נשמתם את אותו אוויר — שניכם תחנקו.$b$,
  $b$השבוע: כמה זמן הקדשת לתחביב אישי?$b$, $b$שעתיים לתחביב אישי השבוע. ספר/י על זה לבן/בת הזוג בחזרה.$b$, $b$אל תרגיש/י אשמה על הזמן הנפרד. הוא משקיע בזוגיות, לא גוזל ממנה.$b$, $b$שניכם נהנים מתחביבים אישיים — וחזרה מהם מרגישה עוד יותר טוב.$b$
)
