-- Row #39: שלב 1 · חברות ושותפות יומיומית · הזמן השלישי — הזוגיות לבד, בלי ילדים
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'friendship' LIMIT 1),
  'csv-s1-friendship-039',
  $b$הזמן השלישי — הזוגיות לבד, בלי ילדים$b$,
  $b$מחקרי גוטמן וצוותו עקבו אחרי זוגות לאורך תקופת ההורות. הממצא הברור: 67% מהזוגות חווים ירידה משמעותית בסיפוק הזוגי בשנתיים הראשונות אחרי הולדת הילד הראשון. הסיבה אינה הילד עצמו — אלא שהזוגיות מאבדת את הזהות העצמאית שלה.

מה קורה: הזוג הופך 'הורים יחד' באופן בלעדי. כל שיחה היא על הילד. כל ערב בילדים. כל סוף שבוע מתנהל סביבם. הזוגיות נמחקת לטובת ההורות. בהתחלה זה נראה 'אצילי' — אנחנו 'נותנים הכל לילדים'. אבל אחרי שנה-שנתיים, הוא והיא הופכים זרים שעובדים ביחד על פרויקט.

הזוגות שמספרים על סיפוק גבוה גם אחרי הולדת ילדים הם אלה ששומרים על 'זמן זוגי' — זמן שבו הם לא הורים, רק אוהבים. וזה לא צריך להיות הרבה. דייט אחד בשבועיים. ערב חופשי בחודש. סוף שבוע ללא ילדים פעם בכמה חודשים.

האירוניה: זה גם טוב לילדים. ילדים שגדלים אצל הורים שאוהבים זה את זה — בכל זוגיות שלמה, לא רק 'משפחה' — מקבלים הון רגשי גדול יותר מאשר ילדים שהוריהם 'הקריבו את עצמם בשבילם'. הקרבה אינה אהבה. אהבה היא נוכחות, גם של ההורים זה לזה.

הקושי הראשי הוא לוגיסטי. בייביסיטרים יקרים. הסבים לא תמיד זמינים. הילדים לפעמים בוכים בפרידה. אבל אלה לא תירוצים — אלה אתגרים. זוגות שמקבלים את האתגר ויוצרים פתרונות, מרוויחים. אלה שמרימים ידיים, מפסידים.

טיפ פרקטי: הסכימו על 'חוק שני שעות'. שעתיים בשבוע, בלי שום קשר לילדים, אתם זוג. לא ארוחת פיצה עם הילדים בטלוויזיה — דייט אמיתי. ועדיין בבית — אחרי שהם נרדמו, אם אין ברירה — רק בלי טלפונים, בלי טלוויזיה. ערב משלכם.

הזוגיות שמשרידה את ההורות היא לא הזוגיות שמוותרת על עצמה. היא הזוגיות שיודעת ששני הצדדים — ההורות והאהבה — צריכים זמן. בלי איזון, אחד מהם דועך. ובמקרים רבים — שניהם.

ההורים הטובים ביותר הם אנשים שמאוהבים. ולכן השקעה בזוגיות היא, פרדוקסלית, גם השקעה בילדים.$b$,
  $b$קבעו דייט שבועי או דו-שבועי. שעתיים לפחות. בלי ילדים. בלי 'מה הילדים עושים'. רק שניכם. אם אין בייביסיטר — נסו 'דייט אחרי שינה' (אחרי 21:00 בבית). אבל אסור 'דייט ואז ילדים'.$b$,
  10039, 0, true, 'both',
  1,
  $b$Gottman + clinical research on parenting and couples$b$, $b$Gottman + clinical research on parenting and couples$b$,
  $b$מחקר: הופך הילדים, סיפוק זוגי יורד ב-67%. הסיבה: הזוגיות הופכת ל'הורות יחד' — לא ל'אהבה יחד'. זוגות שמשמרים 'זמן זוגי' (בלי ילדים) שורדים את ההורות הרבה יותר טוב.$b$, $b$1) לחשוב ש'הילדים בראש סדר העדיפויות' תמיד. 2) לדחות חופשות זוגיות עד 'אחרי שיגדלו'. 3) להפוך כל ערב ל'משפחה' — ואף ערב ל'זוגיות'. 4) לוותר על דייטים בגלל לוגיסטיקה.$b$, $b$הזוגיות כמו עץ. הילדים הם הענפים. בלי גזע חזק, הענפים נופלים. השקיית הגזע היא לא אנוכיות — היא טובת הכלל.$b$,
  $b$השבוע: כמה זמן בילית/ם 'כזוג' — לא 'כהורים'?$b$, $b$דייט אחד השבוע — שעתיים לפחות, בלי ילדים. אם אין יציאה — דייט בית אחרי השינה שלהם.$b$, $b$אל תדחה/י דייטים. אל תניח/י ש'יש זמן בעוד שנה'.$b$, $b$אתם זוכרים שאתם זוג — לא רק הורים. וזה משפיע על האווירה בבית.$b$
)
