-- Row #40: שלב 1 · חברות ושותפות יומיומית · מסכים בזוגיות — הצרה השקטה
INSERT INTO public.journey_items (
  category_id, slug, title_he, body_he, task_he,
  sort_order, default_offset_days, is_active, audience,
  stage, source_attribution_he, source_attribution_en,
  expert_insight_he, common_mistakes_he, metaphor_he,
  measurement_he, do_this_week_he, dont_this_week_he, progress_marker_he
) VALUES (
  (SELECT id FROM public.journey_categories WHERE assessment_priority_key = 'friendship' LIMIT 1),
  'csv-s1-friendship-040',
  $b$מסכים בזוגיות — הצרה השקטה$b$,
  $b$שרי טרקל, פסיכולוגית מ-MIT, חקרה במשך שני עשורים את ההשפעה של טכנולוגיה על קשרים אנושיים. הממצא המרכזי שלה: הטלפון הסלולרי משנה את הדרך בה אנחנו נוכחים אחד עם השני — לעיתים קרובות, לרעה.

המונח 'phubbing' (Phone + Snubbing) מתאר את הפעולה של להתעלם מאדם נוכח לטובת מישהו בטלפון. במחקר על זוגות, נמצא שזוגות שעוסקים ב-phubbing הדדי באופן קבוע מדווחים על ירידה משמעותית בסיפוק הזוגי, גם בלי שיש 'בעיה' אחרת. הטלפון הוא הבעיה.

הסיבה היא נוכחות. כשאני בטלפון, אני לא נוכח/ת באמת ליד בן/בת הזוג. אני 'במקום אחר'. וגם אם אני 'רק לרגע', בן/בת הזוג מקבל/ת את המסר: 'משהו אחר חשוב יותר ממך עכשיו'. בעבר, רק בעבודה הייתי 'במקום אחר'. היום, גם בארוחה, גם בערב, גם במיטה.

האירוניה היא שאנחנו משתמשים בטלפון בדיוק לחיבור — אבל החיבור הזה (להודעות מחברים, לרשתות) בא על חשבון החיבור החי. אנחנו 'מחוברים' ל-100 אנשים, ומנותקים מהאחד שיושב מולנו.

הפתרון אינו לזרוק את הטלפון. הוא להגדיר גבולות. טרקל מציעה 'אזורים נטולי מסך': מקומות בבית או זמנים ביום שבהם הטלפון לא נכנס. המומלצים: שולחן הארוחה, חדר השינה, השעה לאחר ההגעה הביתה, השעה לפני השינה. כל אחד מאלה הופך לזמן זוגיות איכותית — לא משעמם, אלא חי.

ההסכם הזוגי הוא קריטי. שני הצדדים חייבים להסכים. אם אחד שומר על הגבולות והשני לא, נוצרת תחושה של 'אני יותר משקיע/ה'. הסכם הדדי הופך את זה לטקס משותף — לא לוויתור של אחד.

בהתחלה זה לא קל. הטלפון הוא 'התמכרות' לפי כל מבחן ההגדרה. הגוף מבקש אותו. אבל אחרי שבוע של גבולות, רוב הזוגות מספרים שהם מרגישים אחרת. השיחות עמוקות יותר. הקשרים חוזרים. הם זוכרים מה זה לאכול ארוחה ולהסתכל אחד בעיני השני.

טרקל מסכמת: "אנחנו לא צריכים פחות טכנולוגיה — אנחנו צריכים יותר נוכחות. הזוגיות שלנו זקוקה לאדם שלם, לא לחצי שמתערבב במכשיר".$b$,
  $b$הסכימו על 'אזורים נטולי טלפון' בבית: שולחן ארוחה, חדר שינה, סלון בערב לאחר 21:00. שמרו על זה שבוע. שימו לב כמה פעמים תרצו לקחת את הטלפון — וכמה זה משנה לאיכות הזמן.$b$,
  10040, 0, true, 'both',
  1,
  $b$Sherry Turkle, Reclaiming Conversation + clinical updates$b$, $b$Sherry Turkle, Reclaiming Conversation + clinical updates$b$,
  $b$טרקל: 'phubbing' (התעלמות מבן/בת הזוג לטובת הטלפון) הוא אחד הגורמים החדשים לפירוק זוגיות. כל פעם שאני בטלפון בנוכחות בן/בת הזוג, אני משדר/ת 'משהו אחר חשוב יותר'. זה מצטבר.$b$, $b$1) לאכול ארוחה מול טלפון. 2) להשיב להודעה באמצע שיחה זוגית. 3) לחשוב 'זה רק רגע, הוא/היא לא מבחין/ה'. 4) להסכים שהטלפון יהיה בחדר השינה.$b$, $b$טלפון בזוגיות כמו אדם שלישי בחדר. אתה לא צריך לדבר איתו — אבל הוא שם, ובן/בת הזוג שלך יודע/ת.$b$,
  $b$השבוע: כמה פעמים תפסת את עצמך בטלפון בנוכחות בן/בת הזוג?$b$, $b$הגדירו 3 אזורים נטולי טלפון. שמרו עליהם שבוע.$b$, $b$אל תשיב/י להודעה באמצע שיחה זוגית. אל תיכנס/י לטלפון בשולחן.$b$, $b$אתם נוכחים אחד עם השני — והטלפון הוא כלי, לא נוכחות שלישית.$b$
)
